 27→func newTrailCmd() *cobra.Command {
 28→	cmd := &cobra.Command{
 29→		Use:    "trail",
 30→		Short:  "Manage trails for your branches",
 31→		Hidden: true,
 32→		Long: `Trails are branch-centric work tracking abstractions. They describe the
 33→"why" and "what" of your work, while checkpoints capture the "how" and "when".
 34→
 35→Running 'entire trail' without a subcommand shows the trail for the current
 36→branch, or lists all trails if no trail exists for the current branch.`,
 37→		RunE: func(cmd *cobra.Command, _ []string) error {
 38→			return runTrailShow(cmd.OutOrStdout())
 39→		},
 40→	}
 41→
 42→	cmd.AddCommand(newTrailListCmd())
 43→	cmd.AddCommand(newTrailCreateCmd())
 44→	cmd.AddCommand(newTrailUpdateCmd())
 45→
 46→	return cmd
 47→}
 48→
 49→// runTrailShow shows the trail for the current branch, or falls through to list.
 50→func runTrailShow(w io.Writer) error {
 51→	branch, err := GetCurrentBranch(context.Background())
 52→	if err != nil {
 53→		return runTrailListAll(w, "", false, false)
 54→	}
 55→
 56→	repo, err := strategy.OpenRepository(context.Background())
 57→	if err != nil {
 58→		return fmt.Errorf("failed to open repository: %w", err)
 59→	}
 60→
 61→	store := trail.NewStore(repo)
 62→	metadata, err := store.FindByBranch(branch)
 63→	if err != nil || metadata == nil {
 64→		return runTrailListAll(w, "", false, false)
 65→	}
 66→
 67→	printTrailDetails(w, metadata)
 68→	return nil
 69→}
 70→
 71→func printTrailDetails(w io.Writer, m *trail.Metadata) {
 72→	fmt.Fprintf(w, "Trail: %s\n", m.Title)
 73→	fmt.Fprintf(w, "  ID:      %s\n", m.TrailID)
 74→	fmt.Fprintf(w, "  Branch:  %s\n", m.Branch)
 75→	fmt.Fprintf(w, "  Base:    %s\n", m.Base)
 76→	fmt.Fprintf(w, "  Status:  %s\n", m.Status)
 77→	fmt.Fprintf(w, "  Author:  %s\n", m.Author)
 78→	if m.Body != "" {
 79→		fmt.Fprintf(w, "  Body:    %s\n", m.Body)
 80→	}
 81→	if len(m.Labels) > 0 {
 82→		fmt.Fprintf(w, "  Labels:  %s\n", strings.Join(m.Labels, ", "))
 83→	}
 84→	if len(m.Assignees) > 0 {
 85→		fmt.Fprintf(w, "  Assignees: %s\n", strings.Join(m.Assignees, ", "))
 86→	}
 87→	fmt.Fprintf(w, "  Created: %s\n", m.CreatedAt.Format(time.RFC3339))
 88→	fmt.Fprintf(w, "  Updated: %s\n", m.UpdatedAt.Format(time.RFC3339))
 89→}
 90→
 91→func newTrailListCmd() *cobra.Command {
 92→	var statusFilter string
 93→	var jsonOutput bool
 94→	var showAll bool
 95→
 96→	cmd := &cobra.Command{
 97→		Use:   "list",
 98→		Short: "List all trails",
 99→		RunE: func(cmd *cobra.Command, _ []string) error {
100→			return runTrailListAll(cmd.OutOrStdout(), statusFilter, jsonOutput, showAll)
101→		},
102→	}
103→
104→	cmd.Flags().StringVar(&statusFilter, "status", "", "Filter by status (draft, open, in_progress, in_review, merged, closed)")
105→	cmd.Flags().BoolVar(&jsonOutput, "json", false, "Output as JSON")
106→	cmd.Flags().BoolVarP(&showAll, "all", "a", false, "Include merged and closed trails")
107→
108→	return cmd
