584→// slugifyTitle converts a title string into a branch-friendly slug.
585→// Example: "Add user authentication" -> "add-user-authentication"
586→func slugifyTitle(title string) string {
587→	s := strings.ToLower(strings.TrimSpace(title))
588→	// Replace spaces and underscores with hyphens
589→	s = strings.NewReplacer(" ", "-", "_", "-").Replace(s)
590→	// Remove anything that's not alphanumeric, hyphen, or slash
591→	var b strings.Builder
592→	prevHyphen := false
593→	for _, r := range s {
594→		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '/' {
595→			b.WriteRune(r)
596→			prevHyphen = false
597→		} else if r == '-' && !prevHyphen {
598→			b.WriteRune('-')
599→			prevHyphen = true
600→		}
601→	}
602→	return strings.Trim(b.String(), "-")
603→}
