248→// BranchExistsOnRemote checks if a branch exists on the origin remote.
249→// Returns true if the branch is tracked on origin, false otherwise.
250→func BranchExistsOnRemote(ctx context.Context, branchName string) (bool, error) {
251→	repo, err := openRepository(ctx)
252→	if err != nil {
253→		return false, fmt.Errorf("failed to open git repository: %w", err)
254→	}
255→
256→	// Check for remote reference: refs/remotes/origin/<branchName>
257→	_, err = repo.Reference(plumbing.NewRemoteReferenceName("origin", branchName), true)
258→	if err != nil {
259→		if errors.Is(err, plumbing.ErrReferenceNotFound) {
260→			return false, nil
261→		}
262→		return false, fmt.Errorf("failed to check remote branch: %w", err)
263→	}
264→
265→	return true, nil
266→}
