268→// BranchExistsLocally checks if a local branch exists.
269→func BranchExistsLocally(ctx context.Context, branchName string) (bool, error) {
270→	repo, err := openRepository(ctx)
271→	if err != nil {
272→		return false, fmt.Errorf("failed to open git repository: %w", err)
273→	}
274→
275→	_, err = repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
276→	if err != nil {
277→		if errors.Is(err, plumbing.ErrReferenceNotFound) {
278→			return false, nil
279→		}
280→		return false, fmt.Errorf("failed to check branch: %w", err)
281→	}
282→
283→	return true, nil
284→}
