288→// deletes untracked files (see https://github.com/go-git/go-git/issues/970).
289→// Should be switched back to go-git once we upgrade to go-git v6
290→// Returns an error if the ref doesn't exist or checkout fails.
291→func CheckoutBranch(ctx context.Context, ref string) error {
