611→// createBranch creates a new local branch pointing at HEAD without checking it out.
612→func createBranch(repo *git.Repository, branchName string) error {
613→	head, err := repo.Head()
614→	if err != nil {
615→		return fmt.Errorf("failed to get HEAD: %w", err)
616→	}
617→	ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), head.Hash())
618→	if err := repo.Storer.SetReference(ref); err != nil {
619→		return fmt.Errorf("failed to create branch ref: %w", err)
620→	}
621→	return nil
622→}
623→
624→// pushBranchToOrigin pushes a branch to the origin remote.
625→func pushBranchToOrigin(branchName string) error {
626→	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
627→	defer cancel()
628→	cmd := exec.CommandContext(ctx, "git", "push", "--no-verify", "-u", "origin", branchName)
629→	if output, err := cmd.CombinedOutput(); err != nil {
630→		return fmt.Errorf("%s: %w", strings.TrimSpace(string(output)), err)
631→	}
632→	return nil
633→}
