625→// DeleteShadowBranch deletes the shadow branch for the given base commit and worktree.
626→// worktreeID should be empty for main worktree or the internal git worktree name for linked worktrees.
627→// Uses git CLI instead of go-git's RemoveReference because go-git v5 doesn't properly
628→// persist deletions with packed refs or worktrees.
629→func (s *GitStore) DeleteShadowBranch(ctx context.Context, baseCommit, worktreeID string) error {
630→	shadowBranchName := ShadowBranchNameForCommit(baseCommit, worktreeID)
631→	cmd := exec.CommandContext(ctx, "git", "branch", "-D", "--", shadowBranchName)
632→	if output, err := cmd.CombinedOutput(); err != nil {
633→		return fmt.Errorf("failed to delete shadow branch %s: %s: %w", shadowBranchName, strings.TrimSpace(string(output)), err)
