671→// getOrCreateShadowBranch gets or creates the shadow branch for checkpoints.
672→// Returns (parentHash, baseTreeHash, error).
673→func (s *GitStore) getOrCreateShadowBranch(branchName string) (plumbing.Hash, plumbing.Hash, error) {
674→	refName := plumbing.NewBranchReferenceName(branchName)
675→	ref, err := s.repo.Reference(refName, true)
676→
677→	if err == nil {
678→		// Branch exists
679→		commit, err := s.repo.CommitObject(ref.Hash())
680→		if err != nil {
681→			return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit object: %w", err)
682→		}
683→		return ref.Hash(), commit.TreeHash, nil
684→	}
685→
686→	// Branch doesn't exist, use current HEAD's tree as base
687→	head, err := s.repo.Head()
688→	if err != nil {
689→		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get HEAD: %w", err)
690→	}
691→
692→	headCommit, err := s.repo.CommitObject(head.Hash())
693→	if err != nil {
694→		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get HEAD commit: %w", err)
695→	}
696→
697→	return plumbing.ZeroHash, headCommit.TreeHash, nil
698→}
