773→// FlattenTree recursively flattens a tree into a map of full paths to entries.
774→func FlattenTree(repo *git.Repository, tree *object.Tree, prefix string, entries map[string]object.TreeEntry) error {
775→	for _, entry := range tree.Entries {
776→		fullPath := entry.Name
777→		if prefix != "" {
778→			fullPath = prefix + "/" + entry.Name
779→		}
780→
781→		if entry.Mode == filemode.Dir {
782→			// Recurse into subtree
783→			subtree, err := repo.TreeObject(entry.Hash)
784→			if err != nil {
785→				return fmt.Errorf("failed to get subtree %s: %w", fullPath, err)
786→			}
787→			if err := FlattenTree(repo, subtree, fullPath, entries); err != nil {
788→				return err
789→			}
790→		} else {
791→			entries[fullPath] = object.TreeEntry{
792→				Name: fullPath,
793→				Mode: entry.Mode,
794→				Hash: entry.Hash,
795→			}
796→		}
797→	}
798→	return nil
799→}

