// BranchStatus represents the lifecycle status of a branch within a trail.
type BranchStatus string

const (
	BranchOpen      BranchStatus = "open"
	BranchMerged    BranchStatus = "merged"
	BranchDiscarded BranchStatus = "discarded"
)

// IsValid returns true if the branch status is recognized.
func (s BranchStatus) IsValid() bool {
	switch s {
	case BranchOpen, BranchMerged, BranchDiscarded:
		return true
	}
	return false
}

// Intent is a typed reference to the work's purpose — a spec file, issue, URL, or inline text.
type Intent struct {
	Kind       string      `json:"kind"`                // file, url, issue, inline
	Value      string      `json:"value"`               // path, URL, issue ID, inline text
	Content    string      `json:"content,omitempty"`    // resolved intent text (cached)
	Amendments []Amendment `json:"amendments,omitempty"`
}

// Amendment records a change to the intent with reasoning.
type Amendment struct {
	Description string    `json:"description"`
	Reasoning   string    `json:"reasoning"`
	Timestamp   time.Time `json:"timestamp"`
}

// BranchEntry tracks a branch serving a trail's intent.
type BranchEntry struct {
	ID         string       `json:"id"`
	Name       string       `json:"name"`
	BaseBranch string       `json:"base_branch"`
	BaseCommit string       `json:"base_commit,omitempty"`
	Status     BranchStatus `json:"status"`
	PR         *PRRef       `json:"pr,omitempty"`
	AddedAt    time.Time    `json:"added_at"`
}

// PRRef is a replaceable reference to a pull request.
type PRRef struct {
	Number int    `json:"number"`
	URL    string `json:"url,omitempty"`
}

// VerificationEvent records a verification action on a trail or branch.
type VerificationEvent struct {
	Kind      string    `json:"kind"`
	BranchID  string    `json:"branch_id,omitempty"`
	Status    string    `json:"status"`
	Timestamp time.Time `json:"timestamp"`
	Details   string    `json:"details,omitempty"`
}

// Verification holds the list of verification events for a trail.
type Verification struct {
	Events []VerificationEvent `json:"events"`
}
