func TestMetadata_FindBranch(t *testing.T) {
	t.Parallel()

	m := &Metadata{
		TrailID: "a1b2c3d4e5f6",
		Branches: []BranchEntry{
			{ID: "uuid-1", Name: "feature/auth-core"},
			{ID: "uuid-2", Name: "feature/auth-api"},
		},
	}

	entry := m.FindBranch("feature/auth-api")
	if entry == nil {
		t.Fatal("expected to find branch")
	}
	if entry.ID != "uuid-2" {
		t.Errorf("expected uuid-2, got %s", entry.ID)
	}

	if m.FindBranch("nonexistent") != nil {
		t.Error("expected nil for nonexistent branch")
	}
}

func TestMetadata_ActiveBranchName(t *testing.T) {
	t.Parallel()

	// With Branches
	m1 := &Metadata{Branches: []BranchEntry{{Name: "feature/new"}}}
	if got := m1.ActiveBranchName(); got != "feature/new" {
		t.Errorf("expected feature/new, got %s", got)
	}

	// Legacy fallback
	m2 := &Metadata{Branch: "feature/old"}
	if got := m2.ActiveBranchName(); got != "feature/old" {
		t.Errorf("expected feature/old, got %s", got)
	}

	// Empty
	m3 := &Metadata{}
	if got := m3.ActiveBranchName(); got != "" {
		t.Errorf("expected empty, got %s", got)
	}
}

func TestHumanizeBranchName(t *testing.T) {

// Metadata represents the metadata for a trail, matching the web PR format.
type Metadata struct {
	TrailID   ID         `json:"trail_id"`
	Title     string     `json:"title"`
	Body      string     `json:"body"`
	Status    Status     `json:"status"`
	Author    string     `json:"author"`
	Assignees []string   `json:"assignees"`
	Labels    []string   `json:"labels"`
	CreatedAt time.Time  `json:"created_at"`
	UpdatedAt time.Time  `json:"updated_at"`
	MergedAt  *time.Time `json:"merged_at,omitempty"`
	Priority  Priority   `json:"priority,omitempty"`
	Type      Type       `json:"type,omitempty"`
	Reviewers []Reviewer `json:"reviewers,omitempty"`

	// Multi-branch fields
	Intent   *Intent       `json:"intent,omitempty"`
	Branches []BranchEntry `json:"branches,omitempty"`
	Summary  string        `json:"summary,omitempty"`

	// Legacy single-branch fields (kept for backward compat reads)
	Branch string `json:"branch,omitempty"`
	Base   string `json:"base,omitempty"`
}

// FindBranch returns the BranchEntry matching the given branch name, or nil.
func (m *Metadata) FindBranch(branchName string) *BranchEntry {
	for i := range m.Branches {
		if m.Branches[i].Name == branchName {
			return &m.Branches[i]
		}
	}
	return nil
}

// ActiveBranchName returns the branch name for trail context.
// Prefers Branches[0].Name if available, falls back to legacy Branch field.
func (m *Metadata) ActiveBranchName() string {
	if len(m.Branches) > 0 {
		return m.Branches[0].Name
	}
	return m.Branch
}

