556→func fetchTrailsBranch() {
557→	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
558→	defer cancel()
559→	branchName := paths.TrailsBranchName
560→	refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/origin/%s", branchName, branchName)
