611→// createBranch creates a new local branch pointing at HEAD without checking it out.
612→func createBranch(repo *git.Repository, branchName string) error {
613→	head, err := repo.Head()
614→	if err != nil {
615→		return fmt.Errorf("failed to get HEAD: %w", err)
616→	}
617→	ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), head.Hash())
618→	if err := repo.Storer.SetReference(ref); err != nil {
619→		return fmt.Errorf("failed to create branch ref: %w", err)
620→	}
621→	return nil
622→}
