624→// pushBranchToOrigin pushes a branch to the origin remote.
625→func pushBranchToOrigin(branchName string) error {
626→	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
627→	defer cancel()
628→	cmd := exec.CommandContext(ctx, "git", "push", "--no-verify", "-u", "origin", branchName)
629→	if output, err := cmd.CombinedOutput(); err != nil {
630→		return fmt.Errorf("%s: %w", strings.TrimSpace(string(output)), err)
631→	}
632→	return nil
