}
```
Update to:
```go
existing, _, findErr := store.FindByBranch(branchName)
if findErr == nil && existing != nil {
    appendCheckpointToExistingTrail(store, existing.TrailID, result.CheckpointID, head.Hash(), result.Prompts)
}
