 39→// EnsureBranch creates the entire/trails/v1 orphan branch if it doesn't exist.
 40→func (s *Store) EnsureBranch() error {
 41→	refName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
 42→	_, err := s.repo.Reference(refName, true)
 43→	if err == nil {
 44→		return nil // Branch already exists
