 66→// Write writes trail metadata, discussion, checkpoints, and verification to the entire/trails/v1 branch.
 67→// Nil arguments are written as empty defaults.
 68→func (s *Store) Write(metadata *Metadata, discussion *Discussion, checkpoints *Checkpoints, verification *Verification) error {
 69→	if metadata.TrailID.IsEmpty() {
 70→		return errors.New("trail ID is required")
 71→	}
 72→
 73→	if err := s.EnsureBranch(); err != nil {
 74→		return fmt.Errorf("failed to ensure trails branch: %w", err)
 75→	}
 76→
 77→	commitHash, rootTreeHash, err := s.getBranchRef()
 78→	if err != nil {
 79→		return fmt.Errorf("failed to get branch ref: %w", err)
 80→	}
 81→
 82→	// Build blob entries for the trail's files
 83→	trailEntries, err := s.buildTrailEntries(metadata, discussion, checkpoints, verification)
 84→	if err != nil {
 85→		return err
 86→	}
 87→
 88→	// Splice into tree at [shard, suffix] — preserves sibling trails automatically
 89→	shard, suffix := metadata.TrailID.ShardParts()
 90→	newTreeHash, err := checkpoint.UpdateSubtree(
 91→		s.repo, rootTreeHash,
 92→		[]string{shard, suffix},
 93→		trailEntries,
 94→		checkpoint.UpdateSubtreeOptions{MergeMode: checkpoint.ReplaceAll},
 95→	)
 96→	if err != nil {
 97→		return fmt.Errorf("failed to update subtree: %w", err)
 98→	}
 99→
100→	commitMsg := fmt.Sprintf("Trail: %s (%s)", metadata.Title, metadata.TrailID)
101→	return s.commitAndUpdateRef(newTreeHash, commitHash, commitMsg)
102→}
