116→	type fileSpec struct {
117→		name string
118→		data any
119→	}
120→	files := []fileSpec{
121→		{metadataFile, metadata},
122→		{discussionFile, discussion},
123→		{checkpointsFile, checkpoints},
124→		{verificationFile, verification},
125→	}
126→
127→	entries := make([]object.TreeEntry, 0, len(files))
128→	for _, f := range files {
