311→
312→	commitHash, rootTreeHash, err := s.getBranchRef()
313→	if err != nil {
314→		return fmt.Errorf("failed to get branch ref: %w", err)
315→	}
316→
317→	// Navigate to the trail's subtree and read only checkpoints.json
318→	shard, suffix := trailID.ShardParts()
319→	trailTree, err := s.navigateToTrailTree(rootTreeHash, shard, suffix)
320→	if err != nil {
321→		return fmt.Errorf("failed to read checkpoints for trail %s: %w", trailID, err)
322→	}
323→
324→	checkpoints, err := s.readCheckpointsFromTrailTree(trailTree)
325→	if err != nil {
326→		return fmt.Errorf("failed to read checkpoints for trail %s: %w", trailID, err)
327→	}
328→
329→	// Prepend new ref (newest first)
330→	checkpoints.Checkpoints = append(checkpoints.Checkpoints, CheckpointRef{})
331→	copy(checkpoints.Checkpoints[1:], checkpoints.Checkpoints[:len(checkpoints.Checkpoints)-1])
332→	checkpoints.Checkpoints[0] = ref
333→
334→	// Create new blob and splice back — MergeKeepExisting preserves metadata.json and discussion.json
335→	checkpointsJSON, err := json.MarshalIndent(checkpoints, "", "  ")
336→	if err != nil {
337→		return fmt.Errorf("failed to marshal checkpoints: %w", err)
338→	}
339→	blobHash, err := checkpoint.CreateBlobFromContent(s.repo, checkpointsJSON)
340→	if err != nil {
341→		return fmt.Errorf("failed to create checkpoints blob: %w", err)
342→	}
343→
344→	newTreeHash, err := checkpoint.UpdateSubtree(
345→		s.repo, rootTreeHash,
346→		[]string{shard, suffix},
347→		[]object.TreeEntry{{Name: checkpointsFile, Mode: filemode.Regular, Hash: blobHash}},
348→		checkpoint.UpdateSubtreeOptions{MergeMode: checkpoint.MergeKeepExisting},
349→	)
350→	if err != nil {
351→		return fmt.Errorf("failed to update subtree: %w", err)
352→	}
353→
354→	commitMsg := fmt.Sprintf("Add checkpoint to trail: %s", trailID)
355→	return s.commitAndUpdateRef(newTreeHash, commitHash, commitMsg)
356→}
357→
358→// Delete removes a trail from the entire/trails/v1 branch.
359→func (s *Store) Delete(trailID ID) error {
360→	if err := ValidateID(string(trailID)); err != nil {
361→		return err
362→	}
363→
364→	if err := s.EnsureBranch(); err != nil {
365→		return fmt.Errorf("failed to ensure trails branch: %w", err)
366→	}
367→
368→	commitHash, rootTreeHash, err := s.getBranchRef()
369→	if err != nil {
370→		return fmt.Errorf("failed to get branch ref: %w", err)
371→	}
372→
373→	// Verify the trail exists by navigating the tree at O(depth)
374→	shard, suffix := trailID.ShardParts()
375→	if _, err := s.navigateToTrailTree(rootTreeHash, shard, suffix); err != nil {
376→		return err
377→	}
378→
379→	// Delete the trail's subtree by removing it from the shard directory
380→	newTreeHash, err := checkpoint.UpdateSubtree(
381→		s.repo, rootTreeHash,
382→		[]string{shard},
383→		nil,
384→		checkpoint.UpdateSubtreeOptions{
385→			MergeMode:   checkpoint.MergeKeepExisting,
386→			DeleteNames: []string{suffix},
387→		},
388→	)
389→	if err != nil {
390→		return fmt.Errorf("failed to update subtree: %w", err)
391→	}
392→
393→	commitMsg := fmt.Sprintf("Delete trail: %s", trailID)
394→	return s.commitAndUpdateRef(newTreeHash, commitHash, commitMsg)
395→}
