397→// navigateToTrailTree walks rootTree → shard → suffix and returns the trail's subtree.
398→func (s *Store) navigateToTrailTree(rootTreeHash plumbing.Hash, shard, suffix string) (*object.Tree, error) {
399→	rootTree, err := s.repo.TreeObject(rootTreeHash)
400→	if err != nil {
401→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
402→	}
403→
404→	shardEntry, err := rootTree.FindEntry(shard)
405→	if err != nil {
406→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
407→	}
408→
409→	shardTree, err := s.repo.TreeObject(shardEntry.Hash)
410→	if err != nil {
411→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
412→	}
413→
414→	trailEntry, err := shardTree.FindEntry(suffix)
415→	if err != nil {
416→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
417→	}
418→
419→	trailTree, err := s.repo.TreeObject(trailEntry.Hash)
420→	if err != nil {
421→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
422→	}
423→
424→	return trailTree, nil
425→}
426→
427→// readCheckpointsFromTrailTree reads checkpoints.json from a trail's subtree.
428→// Returns empty checkpoints if the file doesn't exist yet.
429→func (s *Store) readCheckpointsFromTrailTree(trailTree *object.Tree) (*Checkpoints, error) {
430→	cpEntry, err := trailTree.FindEntry(checkpointsFile)
431→	if err != nil {
432→		// No checkpoints file yet — return empty
433→		return &Checkpoints{Checkpoints: []CheckpointRef{}}, nil
434→	}
435→
436→	blob, err := s.repo.BlobObject(cpEntry.Hash)
437→	if err != nil {
438→		return nil, fmt.Errorf("failed to read checkpoints blob: %w", err)
439→	}
440→
441→	reader, err := blob.Reader()
442→	if err != nil {
443→		return nil, fmt.Errorf("failed to open checkpoints reader: %w", err)
444→	}
445→	defer reader.Close()
446→
447→	var checkpoints Checkpoints
448→	if err := json.NewDecoder(reader).Decode(&checkpoints); err != nil {
449→		return nil, fmt.Errorf("failed to decode checkpoints: %w", err)
450→	}
451→
452→	return &checkpoints, nil
453→}
454→
455→// commitAndUpdateRef creates a commit and updates the trails branch reference.
456→func (s *Store) commitAndUpdateRef(treeHash, parentHash plumbing.Hash, message string) error {
457→	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
458→	commitHash, err := checkpoint.CreateCommit(s.repo, treeHash, parentHash, message, authorName, authorEmail)
459→	if err != nil {
460→		return fmt.Errorf("failed to create commit: %w", err)
461→	}
462→
463→	newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(paths.TrailsBranchName), commitHash)
464→	if err := s.repo.Storer.SetReference(newRef); err != nil {
465→		return fmt.Errorf("failed to update branch reference: %w", err)
466→	}
467→	return nil
468→}
469→
470→// getBranchRef returns the commit hash and root tree hash for the entire/trails/v1 branch HEAD
471→// without flattening the tree. Falls back to remote tracking branch if local is missing.
472→func (s *Store) getBranchRef() (commitHash, rootTreeHash plumbing.Hash, err error) {
473→	refName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
474→	ref, refErr := s.repo.Reference(refName, true)
475→	if refErr != nil {
476→		// Try remote tracking branch
477→		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.TrailsBranchName)
478→		ref, refErr = s.repo.Reference(remoteRefName, true)
479→		if refErr != nil {
480→			return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("trails branch not found: %w", refErr)
481→		}
482→	}
483→
484→	commit, err := s.repo.CommitObject(ref.Hash())
485→	if err != nil {
486→		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit: %w", err)
487→	}
488→
489→	return ref.Hash(), commit.TreeHash, nil
490→}
491→
492→// getBranchTree returns the tree for the entire/trails/v1 branch HEAD.
493→func (s *Store) getBranchTree() (*object.Tree, error) {
494→	_, rootTreeHash, err := s.getBranchRef()
495→	if err != nil {
496→		return nil, err
497→	}
498→
499→	tree, err := s.repo.TreeObject(rootTreeHash)
500→	if err != nil {
501→		return nil, fmt.Errorf("failed to get tree: %w", err)
502→	}
503→
504→	return tree, nil
505→}
