	t.Parallel()
	repo := initTestRepo(t)
	store := NewStore(repo)

	trailID, _ := GenerateID()
	now := time.Now().Truncate(time.Second)

	// Legacy trail with Branch field, no Branches[]
	metadata := &Metadata{
		TrailID:   trailID,
		Branch:    "feature/old-style",
