  1→package trail
  2→
  3→import (
  4→	"encoding/json"
  5→	"errors"
  6→	"fmt"
  7→	"strings"
  8→	"time"
  9→
 10→	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
 11→	"github.com/entireio/cli/cmd/entire/cli/paths"
 12→
 13→	"github.com/go-git/go-git/v6"
 14→	"github.com/go-git/go-git/v6/plumbing"
 15→	"github.com/go-git/go-git/v6/plumbing/filemode"
 16→	"github.com/go-git/go-git/v6/plumbing/object"
 17→)
 18→
 19→const (
 20→	metadataFile     = "metadata.json"
 21→	discussionFile   = "discussion.json"
 22→	checkpointsFile  = "checkpoints.json"
 23→	verificationFile = "verification.json"
 24→)
 25→
 26→// ErrTrailNotFound is returned when a trail cannot be found.
 27→var ErrTrailNotFound = errors.New("trail not found")
 28→
 29→// Store provides CRUD operations for trail metadata on the entire/trails/v1 branch.
 30→type Store struct {
 31→	repo *git.Repository
 32→}
 33→
 34→// NewStore creates a new trail store backed by the given git repository.
 35→func NewStore(repo *git.Repository) *Store {
 36→	return &Store{repo: repo}
 37→}
 38→
 39→// EnsureBranch creates the entire/trails/v1 orphan branch if it doesn't exist.
 40→func (s *Store) EnsureBranch() error {
 41→	refName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
 42→	_, err := s.repo.Reference(refName, true)
 43→	if err == nil {
 44→		return nil // Branch already exists
 45→	}
 46→
 47→	// Create orphan branch with empty tree
 48→	emptyTreeHash, err := checkpoint.BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
 49→	if err != nil {
 50→		return fmt.Errorf("failed to build empty tree: %w", err)
 51→	}
 52→
 53→	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
 54→	commitHash, err := checkpoint.CreateCommit(s.repo, emptyTreeHash, plumbing.ZeroHash, "Initialize trails branch", authorName, authorEmail)
 55→	if err != nil {
 56→		return fmt.Errorf("failed to create initial commit: %w", err)
 57→	}
 58→
 59→	newRef := plumbing.NewHashReference(refName, commitHash)
 60→	if err := s.repo.Storer.SetReference(newRef); err != nil {
 61→		return fmt.Errorf("failed to set branch reference: %w", err)
 62→	}
 63→	return nil
 64→}
 65→
 66→// Write writes trail metadata, discussion, checkpoints, and verification to the entire/trails/v1 branch.
 67→// Nil arguments are written as empty defaults.
 68→func (s *Store) Write(metadata *Metadata, discussion *Discussion, checkpoints *Checkpoints, verification *Verification) error {
 69→	if metadata.TrailID.IsEmpty() {
 70→		return errors.New("trail ID is required")
 71→	}
 72→
 73→	if err := s.EnsureBranch(); err != nil {
 74→		return fmt.Errorf("failed to ensure trails branch: %w", err)
 75→	}
 76→
 77→	commitHash, rootTreeHash, err := s.getBranchRef()
 78→	if err != nil {
 79→		return fmt.Errorf("failed to get branch ref: %w", err)
 80→	}
 81→
 82→	// Build blob entries for the trail's files
 83→	trailEntries, err := s.buildTrailEntries(metadata, discussion, checkpoints, verification)
 84→	if err != nil {
 85→		return err
 86→	}
 87→
 88→	// Splice into tree at [shard, suffix] — preserves sibling trails automatically
 89→	shard, suffix := metadata.TrailID.ShardParts()
 90→	newTreeHash, err := checkpoint.UpdateSubtree(
 91→		s.repo, rootTreeHash,
 92→		[]string{shard, suffix},
 93→		trailEntries,
 94→		checkpoint.UpdateSubtreeOptions{MergeMode: checkpoint.ReplaceAll},
 95→	)
 96→	if err != nil {
 97→		return fmt.Errorf("failed to update subtree: %w", err)
 98→	}
 99→
100→	commitMsg := fmt.Sprintf("Trail: %s (%s)", metadata.Title, metadata.TrailID)
101→	return s.commitAndUpdateRef(newTreeHash, commitHash, commitMsg)
102→}
103→
104→// buildTrailEntries creates blob objects for a trail's files and returns them as tree entries.
105→func (s *Store) buildTrailEntries(metadata *Metadata, discussion *Discussion, checkpoints *Checkpoints, verification *Verification) ([]object.TreeEntry, error) {
106→	if discussion == nil {
107→		discussion = &Discussion{Comments: []Comment{}}
108→	}
109→	if checkpoints == nil {
110→		checkpoints = &Checkpoints{Checkpoints: []CheckpointRef{}}
111→	}
112→	if verification == nil {
113→		verification = &Verification{Events: []VerificationEvent{}}
114→	}
115→
116→	type fileSpec struct {
117→		name string
118→		data any
119→	}
120→	files := []fileSpec{
121→		{metadataFile, metadata},
122→		{discussionFile, discussion},
123→		{checkpointsFile, checkpoints},
124→		{verificationFile, verification},
125→	}
126→
127→	entries := make([]object.TreeEntry, 0, len(files))
128→	for _, f := range files {
129→		jsonBytes, err := json.MarshalIndent(f.data, "", "  ")
130→		if err != nil {
131→			return nil, fmt.Errorf("failed to marshal %s: %w", f.name, err)
132→		}
133→		blobHash, err := checkpoint.CreateBlobFromContent(s.repo, jsonBytes)
134→		if err != nil {
135→			return nil, fmt.Errorf("failed to create %s blob: %w", f.name, err)
136→		}
137→		entries = append(entries, object.TreeEntry{
138→			Name: f.name,
139→			Mode: filemode.Regular,
140→			Hash: blobHash,
141→		})
142→	}
143→
144→	return entries, nil
145→}
146→
147→// Read reads a trail by its ID from the entire/trails/v1 branch.
148→func (s *Store) Read(trailID ID) (*Metadata, *Discussion, *Checkpoints, *Verification, error) {
149→	if err := ValidateID(string(trailID)); err != nil {
150→		return nil, nil, nil, nil, err
151→	}
152→
153→	tree, err := s.getBranchTree()
154→	if err != nil {
155→		return nil, nil, nil, nil, err
156→	}
157→
158→	basePath := trailID.Path() + "/"
159→
160→	// Read metadata
161→	metadataEntry, err := tree.FindEntry(basePath + metadataFile)
162→	if err != nil {
163→		return nil, nil, nil, nil, fmt.Errorf("trail %s not found: %w", trailID, err)
164→	}
165→	metadataBlob, err := s.repo.BlobObject(metadataEntry.Hash)
166→	if err != nil {
167→		return nil, nil, nil, nil, fmt.Errorf("failed to read metadata blob: %w", err)
168→	}
169→	metadataReader, err := metadataBlob.Reader()
170→	if err != nil {
171→		return nil, nil, nil, nil, fmt.Errorf("failed to open metadata reader: %w", err)
172→	}
173→	defer metadataReader.Close()
174→
175→	var metadata Metadata
176→	if err := json.NewDecoder(metadataReader).Decode(&metadata); err != nil {
177→		return nil, nil, nil, nil, fmt.Errorf("failed to decode metadata: %w", err)
178→	}
179→
180→	// Read discussion (optional, may not exist yet)
181→	var discussion Discussion
182→	discussionEntry, err := tree.FindEntry(basePath + discussionFile)
183→	if err == nil {
184→		discussionBlob, blobErr := s.repo.BlobObject(discussionEntry.Hash)
185→		if blobErr == nil {
186→			discussionReader, readerErr := discussionBlob.Reader()
187→			if readerErr == nil {
188→				//nolint:errcheck,gosec // best-effort decode of optional discussion
189→				json.NewDecoder(discussionReader).Decode(&discussion)
190→				_ = discussionReader.Close()
191→			}
192→		}
193→	}
194→
195→	// Read checkpoints (optional, may not exist yet)
196→	var checkpoints Checkpoints
197→	checkpointsEntry, err := tree.FindEntry(basePath + checkpointsFile)
198→	if err == nil {
199→		checkpointsBlob, blobErr := s.repo.BlobObject(checkpointsEntry.Hash)
200→		if blobErr == nil {
201→			checkpointsReader, readerErr := checkpointsBlob.Reader()
202→			if readerErr == nil {
203→				//nolint:errcheck,gosec // best-effort decode of optional checkpoints
204→				json.NewDecoder(checkpointsReader).Decode(&checkpoints)
205→				_ = checkpointsReader.Close()
206→			}
207→		}
208→	}
209→
210→	// Read verification (optional, may not exist for older trails)
211→	var verification Verification
212→	verificationEntry, err := tree.FindEntry(basePath + verificationFile)
213→	if err == nil {
214→		verificationBlob, blobErr := s.repo.BlobObject(verificationEntry.Hash)
215→		if blobErr == nil {
216→			verificationReader, readerErr := verificationBlob.Reader()
217→			if readerErr == nil {
218→				//nolint:errcheck,gosec // best-effort decode of optional verification
219→				json.NewDecoder(verificationReader).Decode(&verification)
220→				_ = verificationReader.Close()
221→			}
222→		}
223→	}
224→
225→	return &metadata, &discussion, &checkpoints, &verification, nil
226→}
