228→// FindByBranch searches all trails for one containing the given branch name.
229→// Returns (metadata, branchEntry, error). branchEntry is nil for legacy single-branch trails.
230→// Returns (nil, nil, nil) if no trail matches.
231→func (s *Store) FindByBranch(branchName string) (*Metadata, *BranchEntry, error) {
232→	trails, err := s.List()
233→	if err != nil {
234→		return nil, nil, err
235→	}
236→
237→	for _, m := range trails {
238→		// Check new Branches[] field first
239→		if len(m.Branches) > 0 {
240→			for i := range m.Branches {
241→				if m.Branches[i].Name == branchName {
242→					return m, &m.Branches[i], nil
243→				}
244→			}
245→			continue
246→		}
247→
248→		// Legacy fallback: single Branch field
249→		if m.Branch == branchName {
250→			return m, nil, nil
251→		}
252→	}
253→
254→	return nil, nil, nil
255→}
