257→// List returns all trail metadata from the entire/trails/v1 branch.
258→func (s *Store) List() ([]*Metadata, error) {
259→	tree, err := s.getBranchTree()
260→	if err != nil {
261→		// Branch doesn't exist yet — no trails
262→		return nil, nil //nolint:nilerr // Expected when no trails exist yet
263→	}
264→
265→	var trails []*Metadata
266→	entries := make(map[string]object.TreeEntry)
267→	if err := checkpoint.FlattenTree(s.repo, tree, "", entries); err != nil {
268→		return nil, fmt.Errorf("failed to flatten tree: %w", err)
269→	}
270→
271→	// Find all metadata.json files
272→	for path, entry := range entries {
273→		if !strings.HasSuffix(path, "/"+metadataFile) {
274→			continue
275→		}
276→
277→		blob, err := s.repo.BlobObject(entry.Hash)
278→		if err != nil {
279→			continue
280→		}
281→		reader, err := blob.Reader()
282→		if err != nil {
283→			continue
284→		}
285→
286→		var metadata Metadata
287→		decodeErr := json.NewDecoder(reader).Decode(&metadata)
288→		_ = reader.Close()
289→		if decodeErr != nil {
290→			continue
291→		}
292→
293→		trails = append(trails, &metadata)
294→	}
295→
296→	return trails, nil
297→}
