299→// Update updates an existing trail's metadata. It reads the current metadata,
300→// applies the provided update function, and writes it back.
301→func (s *Store) Update(trailID ID, updateFn func(*Metadata)) error {
302→	// ValidateID is called by Read, no need to duplicate here
303→	metadata, discussion, checkpoints, verification, err := s.Read(trailID)
304→	if err != nil {
305→		return fmt.Errorf("failed to read trail for update: %w", err)
306→	}
307→
308→	updateFn(metadata)
309→	metadata.UpdatedAt = time.Now()
310→
311→	return s.Write(metadata, discussion, checkpoints, verification)
312→}
