314→// AddCheckpoint prepends a checkpoint reference to a trail's checkpoints list (newest first).
315→// Only reads and writes the checkpoints.json file — metadata and discussion are untouched.
316→func (s *Store) AddCheckpoint(trailID ID, ref CheckpointRef) error {
317→	if err := ValidateID(string(trailID)); err != nil {
318→		return err
319→	}
320→
321→	if err := s.EnsureBranch(); err != nil {
322→		return fmt.Errorf("failed to ensure trails branch: %w", err)
323→	}
324→
325→	commitHash, rootTreeHash, err := s.getBranchRef()
326→	if err != nil {
327→		return fmt.Errorf("failed to get branch ref: %w", err)
328→	}
329→
330→	// Navigate to the trail's subtree and read only checkpoints.json
331→	shard, suffix := trailID.ShardParts()
332→	trailTree, err := s.navigateToTrailTree(rootTreeHash, shard, suffix)
333→	if err != nil {
334→		return fmt.Errorf("failed to read checkpoints for trail %s: %w", trailID, err)
335→	}
336→
337→	checkpoints, err := s.readCheckpointsFromTrailTree(trailTree)
338→	if err != nil {
339→		return fmt.Errorf("failed to read checkpoints for trail %s: %w", trailID, err)
340→	}
341→
342→	// Prepend new ref (newest first)
343→	checkpoints.Checkpoints = append(checkpoints.Checkpoints, CheckpointRef{})
344→	copy(checkpoints.Checkpoints[1:], checkpoints.Checkpoints[:len(checkpoints.Checkpoints)-1])
345→	checkpoints.Checkpoints[0] = ref
346→
347→	// Create new blob and splice back — MergeKeepExisting preserves metadata.json and discussion.json
348→	checkpointsJSON, err := json.MarshalIndent(checkpoints, "", "  ")
349→	if err != nil {
350→		return fmt.Errorf("failed to marshal checkpoints: %w", err)
351→	}
352→	blobHash, err := checkpoint.CreateBlobFromContent(s.repo, checkpointsJSON)
353→	if err != nil {
354→		return fmt.Errorf("failed to create checkpoints blob: %w", err)
355→	}
356→
357→	newTreeHash, err := checkpoint.UpdateSubtree(
358→		s.repo, rootTreeHash,
359→		[]string{shard, suffix},
360→		[]object.TreeEntry{{Name: checkpointsFile, Mode: filemode.Regular, Hash: blobHash}},
361→		checkpoint.UpdateSubtreeOptions{MergeMode: checkpoint.MergeKeepExisting},
362→	)
363→	if err != nil {
364→		return fmt.Errorf("failed to update subtree: %w", err)
365→	}
366→
367→	commitMsg := fmt.Sprintf("Add checkpoint to trail: %s", trailID)
368→	return s.commitAndUpdateRef(newTreeHash, commitHash, commitMsg)
369→}
