371→// Delete removes a trail from the entire/trails/v1 branch.
372→func (s *Store) Delete(trailID ID) error {
373→	if err := ValidateID(string(trailID)); err != nil {
374→		return err
375→	}
376→
377→	if err := s.EnsureBranch(); err != nil {
378→		return fmt.Errorf("failed to ensure trails branch: %w", err)
379→	}
380→
381→	commitHash, rootTreeHash, err := s.getBranchRef()
382→	if err != nil {
383→		return fmt.Errorf("failed to get branch ref: %w", err)
384→	}
385→
386→	// Verify the trail exists by navigating the tree at O(depth)
387→	shard, suffix := trailID.ShardParts()
388→	if _, err := s.navigateToTrailTree(rootTreeHash, shard, suffix); err != nil {
389→		return err
390→	}
391→
392→	// Delete the trail's subtree by removing it from the shard directory
393→	newTreeHash, err := checkpoint.UpdateSubtree(
394→		s.repo, rootTreeHash,
395→		[]string{shard},
396→		nil,
397→		checkpoint.UpdateSubtreeOptions{
398→			MergeMode:   checkpoint.MergeKeepExisting,
399→			DeleteNames: []string{suffix},
400→		},
401→	)
402→	if err != nil {
403→		return fmt.Errorf("failed to update subtree: %w", err)
404→	}
405→
406→	commitMsg := fmt.Sprintf("Delete trail: %s", trailID)
407→	return s.commitAndUpdateRef(newTreeHash, commitHash, commitMsg)
408→}
