410→// navigateToTrailTree walks rootTree → shard → suffix and returns the trail's subtree.
411→func (s *Store) navigateToTrailTree(rootTreeHash plumbing.Hash, shard, suffix string) (*object.Tree, error) {
412→	rootTree, err := s.repo.TreeObject(rootTreeHash)
413→	if err != nil {
414→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
415→	}
416→
417→	shardEntry, err := rootTree.FindEntry(shard)
418→	if err != nil {
419→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
420→	}
421→
422→	shardTree, err := s.repo.TreeObject(shardEntry.Hash)
423→	if err != nil {
424→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
425→	}
426→
427→	trailEntry, err := shardTree.FindEntry(suffix)
428→	if err != nil {
429→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
430→	}
431→
432→	trailTree, err := s.repo.TreeObject(trailEntry.Hash)
433→	if err != nil {
434→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
435→	}
436→
437→	return trailTree, nil
438→}
