440→// readCheckpointsFromTrailTree reads checkpoints.json from a trail's subtree.
441→// Returns empty checkpoints if the file doesn't exist yet.
442→func (s *Store) readCheckpointsFromTrailTree(trailTree *object.Tree) (*Checkpoints, error) {
443→	cpEntry, err := trailTree.FindEntry(checkpointsFile)
444→	if err != nil {
445→		// No checkpoints file yet — return empty
446→		return &Checkpoints{Checkpoints: []CheckpointRef{}}, nil
447→	}
448→
449→	blob, err := s.repo.BlobObject(cpEntry.Hash)
450→	if err != nil {
451→		return nil, fmt.Errorf("failed to read checkpoints blob: %w", err)
452→	}
453→
454→	reader, err := blob.Reader()
455→	if err != nil {
456→		return nil, fmt.Errorf("failed to open checkpoints reader: %w", err)
457→	}
458→	defer reader.Close()
459→
460→	var checkpoints Checkpoints
461→	if err := json.NewDecoder(reader).Decode(&checkpoints); err != nil {
462→		return nil, fmt.Errorf("failed to decode checkpoints: %w", err)
463→	}
464→
465→	return &checkpoints, nil
466→}
