468→// commitAndUpdateRef creates a commit and updates the trails branch reference.
469→func (s *Store) commitAndUpdateRef(treeHash, parentHash plumbing.Hash, message string) error {
470→	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
471→	commitHash, err := checkpoint.CreateCommit(s.repo, treeHash, parentHash, message, authorName, authorEmail)
472→	if err != nil {
473→		return fmt.Errorf("failed to create commit: %w", err)
474→	}
475→
476→	newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(paths.TrailsBranchName), commitHash)
477→	if err := s.repo.Storer.SetReference(newRef); err != nil {
478→		return fmt.Errorf("failed to update branch reference: %w", err)
479→	}
480→	return nil
481→}
482→
483→// getBranchRef returns the commit hash and root tree hash for the entire/trails/v1 branch HEAD
484→// without flattening the tree. Falls back to remote tracking branch if local is missing.
485→func (s *Store) getBranchRef() (commitHash, rootTreeHash plumbing.Hash, err error) {
486→	refName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
487→	ref, refErr := s.repo.Reference(refName, true)
488→	if refErr != nil {
489→		// Try remote tracking branch
490→		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.TrailsBranchName)
491→		ref, refErr = s.repo.Reference(remoteRefName, true)
492→		if refErr != nil {
493→			return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("trails branch not found: %w", refErr)
494→		}
495→	}
496→
497→	commit, err := s.repo.CommitObject(ref.Hash())
498→	if err != nil {
499→		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit: %w", err)
500→	}
501→
502→	return ref.Hash(), commit.TreeHash, nil
503→}
504→
505→// getBranchTree returns the tree for the entire/trails/v1 branch HEAD.
506→func (s *Store) getBranchTree() (*object.Tree, error) {
507→	_, rootTreeHash, err := s.getBranchRef()
508→	if err != nil {
509→		return nil, err
510→	}
511→
512→	tree, err := s.repo.TreeObject(rootTreeHash)
513→	if err != nil {
514→		return nil, fmt.Errorf("failed to get tree: %w", err)
515→	}
516→
517→	return tree, nil
518→}
