484→func formatValidStatuses() string {
485→	statuses := trail.ValidStatuses()
486→	names := make([]string, len(statuses))
487→	for i, s := range statuses {
488→		names[i] = string(s)
489→	}
490→	return strings.Join(names, ", ")
491→}
