493→// runTrailCreateInteractive runs the interactive form for trail creation.
494→// Prompts for title, body, branch (derived from title), and status.
495→func runTrailCreateInteractive(title, body, branch, statusStr *string) error {
496→	// Step 1: Title and body
497→	form := NewAccessibleForm(
498→		huh.NewGroup(
499→			huh.NewInput().
500→				Title("Trail title").
501→				Placeholder("What are you working on?").
502→				Value(title),
503→			huh.NewText().
504→				Title("Body (optional)").
505→				Value(body),
506→		),
507→	)
508→	if err := form.Run(); err != nil {
509→		return fmt.Errorf("form cancelled: %w", err)
510→	}
511→	*title = strings.TrimSpace(*title)
512→	if *title == "" {
513→		return errors.New("trail title is required")
514→	}
515→
516→	// Step 2: Branch (derived from title) and status
517→	suggested := slugifyTitle(*title)
518→	*branch = suggested
519→
520→	// Build status options, excluding done/abandoned
521→	var statusOptions []huh.Option[string]
522→	for _, s := range trail.ValidStatuses() {
523→		if s == trail.StatusDone || s == trail.StatusAbandoned {
524→			continue
525→		}
526→		statusOptions = append(statusOptions, huh.NewOption(string(s), string(s)))
527→	}
528→	if *statusStr == "" {
529→		*statusStr = string(trail.StatusDraft)
530→	}
531→
532→	form = NewAccessibleForm(
533→		huh.NewGroup(
534→			huh.NewInput().
535→				Title("Branch name").
536→				Placeholder(suggested).
537→				Value(branch),
538→			huh.NewSelect[string]().
539→				Title("Status").
540→				Options(statusOptions...).
541→				Value(statusStr),
542→		),
543→	)
544→	if err := form.Run(); err != nil {
545→		return fmt.Errorf("form cancelled: %w", err)
546→	}
547→	*branch = strings.TrimSpace(*branch)
548→	if *branch == "" {
549→		*branch = suggested
550→	}
551→	return nil
552→}
