231→// FindByBranch searches all trails for one containing the given branch name.
232→// Returns (metadata, branchEntry, error). branchEntry is nil for legacy single-branch trails.
233→// Returns (nil, nil, nil) if no trail matches.
234→func (s *Store) FindByBranch(branchName string) (*Metadata, *BranchEntry, error) {
235→	trails, err := s.List()
236→	if err != nil {
237→		return nil, nil, err
238→	}
239→
240→	for _, m := range trails {
241→		// Check new Branches[] field first
242→		if len(m.Branches) > 0 {
243→			for i := range m.Branches {
244→				if m.Branches[i].Name == branchName {
245→					return m, &m.Branches[i], nil
246→				}
247→			}
248→			continue
249→		}
250→
251→		// Legacy fallback: single Branch field
252→		if m.Branch == branchName {
253→			return m, nil, nil
254→		}
255→	}
256→
257→	return nil, nil, nil
258→}
