317→// AddCheckpoint prepends a checkpoint reference to a trail's checkpoints list (newest first).
318→// Only reads and writes the checkpoints.json file — metadata and discussion are untouched.
319→// Uses CAS retry to handle concurrent writes to the trails branch.
320→func (s *Store) AddCheckpoint(trailID ID, ref CheckpointRef) error {
321→	if err := ValidateID(string(trailID)); err != nil {
322→		return err
323→	}
324→
325→	if err := s.EnsureBranch(); err != nil {
326→		return fmt.Errorf("failed to ensure trails branch: %w", err)
327→	}
328→
329→	for attempt := range maxCASRetries {
330→		err := s.addCheckpointOnce(trailID, ref)
331→		if err == nil {
332→			return nil
333→		}
334→		if !errors.Is(err, storage.ErrReferenceHasChanged) {
335→			return err
336→		}
337→		if attempt == maxCASRetries-1 {
338→			return fmt.Errorf("failed to add checkpoint after %d retries: %w", maxCASRetries, err)
339→		}
340→	}
341→	return nil
342→}
