432→// navigateToTrailTree walks rootTree → shard → suffix and returns the trail's subtree.
433→func (s *Store) navigateToTrailTree(rootTreeHash plumbing.Hash, shard, suffix string) (*object.Tree, error) {
434→	rootTree, err := s.repo.TreeObject(rootTreeHash)
435→	if err != nil {
436→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
437→	}
438→
439→	shardEntry, err := rootTree.FindEntry(shard)
440→	if err != nil {
441→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
442→	}
443→
444→	shardTree, err := s.repo.TreeObject(shardEntry.Hash)
445→	if err != nil {
446→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
447→	}
448→
449→	trailEntry, err := shardTree.FindEntry(suffix)
450→	if err != nil {
451→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
452→	}
453→
454→	trailTree, err := s.repo.TreeObject(trailEntry.Hash)
455→	if err != nil {
456→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
457→	}
458→
459→	return trailTree, nil
460→}
