490→// commitAndUpdateRef creates a commit and updates the trails branch reference using CAS.
491→func (s *Store) commitAndUpdateRef(treeHash, parentHash plumbing.Hash, message string) error {
492→	refName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
493→	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
494→
495→	commitHash, err := checkpoint.CreateCommit(s.repo, treeHash, parentHash, message, authorName, authorEmail)
496→	if err != nil {
497→		return fmt.Errorf("failed to create commit: %w", err)
498→	}
499→
500→	newRef := plumbing.NewHashReference(refName, commitHash)
501→	oldRef := plumbing.NewHashReference(refName, parentHash)
502→
503→	err = s.repo.Storer.CheckAndSetReference(newRef, oldRef)
504→	if err != nil {
505→		if errors.Is(err, storage.ErrReferenceHasChanged) {
506→			return fmt.Errorf("trail branch ref changed concurrently: %w", err)
507→		}
508→		return fmt.Errorf("failed to update branch reference: %w", err)
509→	}
510→	return nil
511→}
512→
513→// getBranchRef returns the commit hash and root tree hash for the entire/trails/v1 branch HEAD
514→// without flattening the tree. Falls back to remote tracking branch if local is missing.
515→func (s *Store) getBranchRef() (commitHash, rootTreeHash plumbing.Hash, err error) {
516→	refName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
517→	ref, refErr := s.repo.Reference(refName, true)
518→	if refErr != nil {
519→		// Try remote tracking branch
520→		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.TrailsBranchName)
521→		ref, refErr = s.repo.Reference(remoteRefName, true)
522→		if refErr != nil {
523→			return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("trails branch not found: %w", refErr)
524→		}
525→	}
526→
527→	commit, err := s.repo.CommitObject(ref.Hash())
528→	if err != nil {
529→		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit: %w", err)
530→	}
531→
532→	return ref.Hash(), commit.TreeHash, nil
533→}
534→
535→// getBranchTree returns the tree for the entire/trails/v1 branch HEAD.
536→func (s *Store) getBranchTree() (*object.Tree, error) {
537→	_, rootTreeHash, err := s.getBranchRef()
538→	if err != nil {
539→		return nil, err
540→	}
541→
542→	tree, err := s.repo.TreeObject(rootTreeHash)
543→	if err != nil {
544→		return nil, fmt.Errorf("failed to get tree: %w", err)
545→	}
546→
547→	return tree, nil
548→}
