112→func runTrailListAll(w io.Writer, statusFilter string, jsonOutput, showAll bool) error {
113→	// Fetch remote trails branch so we see trails from collaborators
114→	fetchTrailsBranch()
115→
116→	repo, err := strategy.OpenRepository(context.Background())
117→	if err != nil {
118→		return fmt.Errorf("failed to open repository: %w", err)
119→	}
120→
121→	store := trail.NewStore(repo)
122→	trails, err := store.List()
123→	if err != nil {
124→		return fmt.Errorf("failed to list trails: %w", err)
125→	}
126→
127→	if trails == nil {
128→		trails = []*trail.Metadata{}
129→	}
130→
131→	totalCount := len(trails)
132→
133→	// Apply status filter
134→	if statusFilter != "" {
135→		status := trail.Status(statusFilter)
136→		if !status.IsValid() {
137→			return fmt.Errorf("invalid status %q: valid values are %s", statusFilter, formatValidStatuses())
138→		}
139→		var filtered []*trail.Metadata
140→		for _, t := range trails {
141→			if t.Status == status {
142→				filtered = append(filtered, t)
143→			}
144→		}
145→		trails = filtered
146→	} else if !showAll {
147→		// By default, hide done and abandoned trails
148→		var filtered []*trail.Metadata
149→		for _, t := range trails {
150→			if t.Status != trail.StatusDone && t.Status != trail.StatusAbandoned {
151→				filtered = append(filtered, t)
152→			}
153→		}
154→		trails = filtered
155→	}
156→
157→	// Sort by updated_at descending
158→	sort.Slice(trails, func(i, j int) bool {
159→		return trails[i].UpdatedAt.After(trails[j].UpdatedAt)
160→	})
161→
162→	if jsonOutput {
163→		enc := json.NewEncoder(w)
164→		enc.SetIndent("", "  ")
165→		if err := enc.Encode(trails); err != nil {
166→			return fmt.Errorf("failed to encode JSON: %w", err)
167→		}
168→		return nil
169→	}
170→
171→	if len(trails) == 0 {
172→		hiddenCount := totalCount - len(trails)
173→		if hiddenCount > 0 {
174→			fmt.Fprintf(w, "No active trails found. %d merged/closed trail(s) hidden — use --all to show.\n", hiddenCount)
175→		} else {
176→			fmt.Fprintln(w, "No trails found.")
177→			fmt.Fprintln(w)
178→			fmt.Fprintln(w, "Commands:")
179→			fmt.Fprintln(w, "  entire trail create   Create a trail for the current branch")
180→			fmt.Fprintln(w, "  entire trail list     List all trails")
181→			fmt.Fprintln(w, "  entire trail update   Update trail metadata")
182→		}
183→		return nil
184→	}
185→
186→	// Table output
187→	fmt.Fprintf(w, "%-30s %-40s %-13s %-15s %s\n", "BRANCH", "TITLE", "STATUS", "AUTHOR", "UPDATED")
188→	for _, t := range trails {
189→		branch := stringutil.TruncateRunes(t.Branch, 30, "...")
190→		title := stringutil.TruncateRunes(t.Title, 40, "...")
191→		fmt.Fprintf(w, "%-30s %-40s %-13s %-15s %s\n",
192→			branch, title, t.Status, stringutil.TruncateRunes(t.Author, 15, "..."), timeAgo(t.UpdatedAt))
193→	}
194→
195→	return nil
196→}
