220→//nolint:cyclop // sequential steps for creating a trail — splitting would obscure the flow
221→func runTrailCreate(cmd *cobra.Command, title, body, base, branch, statusStr string, checkout bool) error {
222→	w := cmd.OutOrStdout()
223→	errW := cmd.ErrOrStderr()
224→
225→	repo, err := strategy.OpenRepository(context.Background())
226→	if err != nil {
227→		return fmt.Errorf("failed to open repository: %w", err)
228→	}
229→
230→	// Determine base branch
231→	if base == "" {
232→		base = strategy.GetDefaultBranchName(repo)
233→		if base == "" {
234→			base = defaultBaseBranch
235→		}
236→	}
237→
238→	_, currentBranch, _ := IsOnDefaultBranch(context.Background()) //nolint:errcheck // best-effort detection
239→	interactive := !cmd.Flags().Changed("title") && !cmd.Flags().Changed("branch")
240→
241→	if interactive {
242→		// Interactive flow: title → body → branch (derived) → status
243→		if err := runTrailCreateInteractive(&title, &body, &branch, &statusStr); err != nil {
244→			return err
245→		}
246→	} else {
247→		// Non-interactive: derive missing values from provided flags
248→		if branch == "" {
249→			if cmd.Flags().Changed("title") {
250→				branch = slugifyTitle(title)
251→			} else {
252→				branch = currentBranch
253→			}
254→		}
255→		if title == "" {
256→			title = trail.HumanizeBranchName(branch)
257→		}
258→	}
259→	if branch == "" {
260→		return errors.New("branch name is required")
261→	}
262→
263→	// Create the branch if it doesn't exist
264→	needsCreation := branchNeedsCreation(repo, branch)
265→	if needsCreation {
266→		if err := createBranch(repo, branch); err != nil {
267→			return fmt.Errorf("failed to create branch %q: %w", branch, err)
268→		}
269→		fmt.Fprintf(w, "Created branch %s\n", branch)
270→	} else if currentBranch != branch {
271→		fmt.Fprintf(errW, "Note: trail will be created for branch %q (not the current branch)\n", branch)
272→	}
273→
274→	// Check if trail already exists for this branch
275→	store := trail.NewStore(repo)
276→	existing, _, err := store.FindByBranch(branch)
277→	if err == nil && existing != nil {
278→		fmt.Fprintf(w, "Trail already exists for branch %q (ID: %s)\n", branch, existing.TrailID)
279→		return nil
280→	}
281→
282→	// Determine status
283→	var trailStatus trail.Status
284→	if statusStr != "" {
285→		trailStatus = trail.Status(statusStr)
286→		if !trailStatus.IsValid() {
287→			return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
288→		}
289→	} else {
290→		trailStatus = trail.StatusDraft
291→	}
292→
293→	// Generate trail ID
294→	trailID, err := trail.GenerateID()
295→	if err != nil {
296→		return fmt.Errorf("failed to generate trail ID: %w", err)
297→	}
298→
299→	// Get author (GitHub username, falls back to git user.name)
300→	authorName := getTrailAuthor(repo)
301→
302→	now := time.Now()
303→	metadata := &trail.Metadata{
304→		TrailID:   trailID,
305→		Branch:    branch,
306→		Base:      base,
307→		Title:     title,
308→		Body:      body,
309→		Status:    trailStatus,
310→		Author:    authorName,
311→		Assignees: []string{},
312→		Labels:    []string{},
313→		CreatedAt: now,
314→		UpdatedAt: now,
315→	}
316→
317→	if err := store.Write(metadata, nil, nil, nil); err != nil {
318→		return fmt.Errorf("failed to create trail: %w", err)
319→	}
320→
321→	fmt.Fprintf(w, "Created trail %q for branch %s (ID: %s)\n", title, branch, trailID)
322→
323→	// Push the branch and trail data to origin
324→	if needsCreation {
325→		if err := pushBranchToOrigin(branch); err != nil {
326→			fmt.Fprintf(errW, "Warning: failed to push branch: %v\n", err)
327→		} else {
328→			fmt.Fprintf(w, "Pushed branch %s to origin\n", branch)
329→		}
330→	}
331→	if err := strategy.PushTrailsBranch(context.Background(), "origin"); err != nil {
332→		fmt.Fprintf(errW, "Warning: failed to push trail data: %v\n", err)
333→	}
334→
335→	// Checkout the branch if requested or prompted
336→	if needsCreation && currentBranch != branch {
337→		shouldCheckout := checkout
338→		if !shouldCheckout && !cmd.Flags().Changed("checkout") {
339→			// Interactive: ask whether to checkout
340→			form := NewAccessibleForm(
341→				huh.NewGroup(
342→					huh.NewConfirm().
343→						Title(fmt.Sprintf("Check out branch %s?", branch)).
344→						Value(&shouldCheckout),
345→				),
346→			)
347→			if formErr := form.Run(); formErr == nil && shouldCheckout {
348→				checkout = true
349→			}
350→		}
351→		if checkout {
352→			if err := CheckoutBranch(context.Background(), branch); err != nil {
353→				return fmt.Errorf("failed to checkout branch %q: %w", branch, err)
354→			}
355→			fmt.Fprintf(w, "Switched to branch %s\n", branch)
356→		}
357→	}
358→
359→	return nil
360→}
