384→func runTrailUpdate(w io.Writer, statusStr, title, body, branch string, labelAdd, labelRemove []string) error {
385→	repo, err := strategy.OpenRepository(context.Background())
386→	if err != nil {
387→		return fmt.Errorf("failed to open repository: %w", err)
388→	}
389→
390→	// Determine branch
391→	if branch == "" {
392→		branch, err = GetCurrentBranch(context.Background())
393→		if err != nil {
394→			return fmt.Errorf("failed to determine current branch: %w", err)
395→		}
396→	}
397→
398→	store := trail.NewStore(repo)
399→	metadata, _, err := store.FindByBranch(branch)
400→	if err != nil {
401→		return fmt.Errorf("failed to find trail: %w", err)
402→	}
403→	if metadata == nil {
404→		return fmt.Errorf("no trail found for branch %q", branch)
405→	}
406→
407→	// Interactive mode when no flags are provided
408→	noFlags := statusStr == "" && title == "" && body == "" && labelAdd == nil && labelRemove == nil
409→	if noFlags {
410→		// Build status options with current value as default.
411→		// Exclude "done" and "abandoned" unless the trail is already in that status
412→		// (otherwise the select would silently reset to the first option).
413→		var statusOptions []huh.Option[string]
414→		for _, s := range trail.ValidStatuses() {
415→			if (s == trail.StatusDone || s == trail.StatusAbandoned) && s != metadata.Status {
416→				continue
417→			}
418→			label := string(s)
419→			if s == metadata.Status {
420→				label += " (current)"
421→			}
422→			statusOptions = append(statusOptions, huh.NewOption(label, string(s)))
423→		}
424→		statusStr = string(metadata.Status)
425→		title = metadata.Title
426→		body = metadata.Body
427→
428→		form := NewAccessibleForm(
429→			huh.NewGroup(
430→				huh.NewSelect[string]().
431→					Title("Status").
432→					Options(statusOptions...).
433→					Value(&statusStr),
434→				huh.NewInput().
435→					Title("Title").
436→					Value(&title),
437→				huh.NewText().
438→					Title("Body").
439→					Value(&body),
440→			),
441→		)
442→		if formErr := form.Run(); formErr != nil {
443→			return fmt.Errorf("form cancelled: %w", formErr)
444→		}
445→	}
446→
447→	// Validate status if provided
448→	if statusStr != "" {
449→		status := trail.Status(statusStr)
450→		if !status.IsValid() {
451→			return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
452→		}
453→	}
454→
455→	err = store.Update(metadata.TrailID, func(m *trail.Metadata) {
456→		if statusStr != "" {
457→			m.Status = trail.Status(statusStr)
458→		}
459→		if title != "" {
460→			m.Title = title
461→		}
462→		if body != "" {
463→			m.Body = body
464→		}
465→		for _, l := range labelAdd {
466→			if !slices.Contains(m.Labels, l) {
467→				m.Labels = append(m.Labels, l)
468→			}
469→		}
470→		for _, l := range labelRemove {
471→			m.Labels = slices.DeleteFunc(m.Labels, func(v string) bool { return v == l })
472→		}
473→	})
474→	if err != nil {
475→		return fmt.Errorf("failed to update trail: %w", err)
476→	}
477→
478→	fmt.Fprintf(w, "Updated trail for branch %s\n", branch)
479→	return nil
480→}
