517→	// Step 2: Branch (derived from title) and status
518→	suggested := slugifyTitle(*title)
519→	*branch = suggested
520→
521→	// Build status options, excluding done/abandoned
522→	var statusOptions []huh.Option[string]
523→	for _, s := range trail.ValidStatuses() {
524→		if s == trail.StatusDone || s == trail.StatusAbandoned {
525→			continue
526→		}
527→		statusOptions = append(statusOptions, huh.NewOption(string(s), string(s)))
528→	}
529→	if *statusStr == "" {
530→		*statusStr = string(trail.StatusDraft)
531→	}
532→
533→	form = NewAccessibleForm(
534→		huh.NewGroup(
535→			huh.NewInput().
536→				Title("Branch name").
537→				Placeholder(suggested).
538→				Value(branch),
539→			huh.NewSelect[string]().
540→				Title("Status").
541→				Options(statusOptions...).
542→				Value(statusStr),
543→		),
544→	)
545→	if err := form.Run(); err != nil {
546→		return fmt.Errorf("form cancelled: %w", err)
547→	}
548→	*branch = strings.TrimSpace(*branch)
549→	if *branch == "" {
550→		*branch = suggested
551→	}
552→	return nil
553→}
