555→// fetchTrailsBranch fetches the remote trails branch so we see trails from collaborators.
556→// Best-effort: silently ignores errors (e.g., no remote, no network).
557→func fetchTrailsBranch() {
558→	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
559→	defer cancel()
560→	branchName := paths.TrailsBranchName
561→	refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/origin/%s", branchName, branchName)
