585→// slugifyTitle converts a title string into a branch-friendly slug.
586→// Example: "Add user authentication" -> "add-user-authentication"
587→func slugifyTitle(title string) string {
588→	s := strings.ToLower(strings.TrimSpace(title))
589→	// Replace spaces and underscores with hyphens
590→	s = strings.NewReplacer(" ", "-", "_", "-").Replace(s)
591→	// Remove anything that's not alphanumeric, hyphen, or slash
592→	var b strings.Builder
593→	prevHyphen := false
594→	for _, r := range s {
595→		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '/' {
596→			b.WriteRune(r)
597→			prevHyphen = false
598→		} else if r == '-' && !prevHyphen {
599→			b.WriteRune('-')
600→			prevHyphen = true
601→		}
602→	}
603→	return strings.Trim(b.String(), "-")
604→}
