606→// branchNeedsCreation checks if a branch exists locally.
607→func branchNeedsCreation(repo *git.Repository, branchName string) bool {
608→	_, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
609→	return err != nil
