612→// createBranch creates a new local branch pointing at HEAD without checking it out.
613→func createBranch(repo *git.Repository, branchName string) error {
614→	head, err := repo.Head()
615→	if err != nil {
616→		return fmt.Errorf("failed to get HEAD: %w", err)
617→	}
618→	ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), head.Hash())
619→	if err := repo.Storer.SetReference(ref); err != nil {
620→		return fmt.Errorf("failed to create branch ref: %w", err)
621→	}
622→	return nil
623→}
