635→//nolint:cyclop // sequential steps for adding a branch — splitting would obscure the flow
636→func newTrailBranchAddCmd() *cobra.Command {
637→	var baseBranch string
638→	var trailFlag string
639→
640→	cmd := &cobra.Command{
641→		Use:   "add [branch-name]",
642→		Short: "Add a branch to a trail",
643→		Long:  "Adds the current branch (or a named branch) to a trail. Uses stateless lookup to find the trail from the current branch.",
644→		Args:  cobra.MaximumNArgs(1),
645→		RunE: func(cmd *cobra.Command, args []string) error {
646→			repo, err := strategy.OpenRepository(context.Background())
647→			if err != nil {
648→				return fmt.Errorf("failed to open repository: %w", err)
649→			}
650→
651→			store := trail.NewStore(repo)
652→
653→			// Determine branch name to add
654→			var branchName string
655→			if len(args) > 0 {
656→				branchName = args[0]
657→			} else {
658→				branchName, err = GetCurrentBranch(context.Background())
659→				if err != nil {
660→					return fmt.Errorf("could not determine current branch: %w", err)
661→				}
662→			}
663→
664→			// Check if branch is already in a trail
665→			existing, existingEntry, findErr := store.FindByBranch(branchName)
666→			if findErr != nil {
667→				return fmt.Errorf("failed to look up branch: %w", findErr)
668→			}
669→			if existing != nil && existingEntry != nil {
670→				fmt.Fprintf(cmd.ErrOrStderr(), "Branch %q is already in trail %q\n", branchName, existing.Title)
671→				return nil
672→			}
673→
674→			// Resolve which trail to add to
675→			var targetTrail *trail.Metadata
676→			if trailFlag != "" {
677→				if err := trail.ValidateID(trailFlag); err != nil {
678→					return fmt.Errorf("invalid trail ID: %w", err)
679→				}
680→				targetTrail, _, _, _, err = store.Read(trail.ID(trailFlag))
681→				if err != nil {
682→					return fmt.Errorf("trail %s not found: %w", trailFlag, err)
683→				}
684→			} else {
685→				// Try to find trail from current branch (if adding a different branch)
686→				currentBranch, branchErr := GetCurrentBranch(context.Background())
687→				if branchErr == nil && currentBranch != branchName {
688→					targetTrail, _, _ = store.FindByBranch(currentBranch) //nolint:errcheck // best-effort lookup; nil targetTrail handled below
689→				}
690→				if targetTrail == nil {
691→					return errors.New("cannot determine trail; use --trail <id> to specify")
692→				}
693→			}
694→
695→			// Determine base branch
696→			if baseBranch == "" {
697→				baseBranch = getDefaultBranch(repo)
698→			}
699→
700→			// Generate branch entry ID
701→			entryID, err := trail.GenerateID()
702→			if err != nil {
703→				return fmt.Errorf("failed to generate branch ID: %w", err)
704→			}
705→
706→			entry := trail.BranchEntry{
707→				ID:         entryID.String(),
708→				Name:       branchName,
709→				BaseBranch: baseBranch,
710→				Status:     trail.BranchOpen,
711→				AddedAt:    time.Now().UTC(),
712→			}
713→
714→			if err := store.Update(targetTrail.TrailID, func(m *trail.Metadata) {
715→				m.Branches = append(m.Branches, entry)
716→			}); err != nil {
717→				return fmt.Errorf("failed to add branch: %w", err)
718→			}
719→
720→			fmt.Fprintf(cmd.OutOrStdout(), "Added branch %q to trail %q\n", branchName, targetTrail.Title)
721→			return nil
722→		},
723→	}
724→
725→	cmd.Flags().StringVar(&baseBranch, "base", "", "Base branch for stacking (default: repository default branch)")
726→	cmd.Flags().StringVar(&trailFlag, "trail", "", "Trail ID to add branch to")
727→
728→	return cmd
729→}
