731→// getDefaultBranch returns the default branch name for the repository.
732→func getDefaultBranch(repo *git.Repository) string {
733→	name := strategy.GetDefaultBranchName(repo)
734→	if name == "" {
735→		return defaultBaseBranch
736→	}
737→	return name
738→}
