740→// pushBranchToOrigin pushes a branch to the origin remote.
741→func pushBranchToOrigin(branchName string) error {
742→	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
743→	defer cancel()
744→	cmd := exec.CommandContext(ctx, "git", "push", "--no-verify", "-u", "origin", branchName)
745→	if output, err := cmd.CombinedOutput(); err != nil {
746→		return fmt.Errorf("%s: %w", strings.TrimSpace(string(output)), err)
747→	}
748→	return nil
749→}
