 20→const (
 21→	metadataFile     = "metadata.json"
 22→	discussionFile   = "discussion.json"
 23→	checkpointsFile  = "checkpoints.json"
 24→	verificationFile = "verification.json"
 25→
 26→	maxCASRetries = 5
 27→)
 28→
 29→// ErrTrailNotFound is returned when a trail cannot be found.
 30→var ErrTrailNotFound = errors.New("trail not found")
 31→
 32→// Store provides CRUD operations for trail metadata on the entire/trails/v1 branch.
 33→type Store struct {
 34→	repo *git.Repository
 35→}
 36→
 37→// NewStore creates a new trail store backed by the given git repository.
 38→func NewStore(repo *git.Repository) *Store {
 39→	return &Store{repo: repo}
 40→}
 41→
 42→// EnsureBranch creates the entire/trails/v1 orphan branch if it doesn't exist.
 43→func (s *Store) EnsureBranch() error {
 44→	refName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
 45→	_, err := s.repo.Reference(refName, true)
 46→	if err == nil {
 47→		return nil // Branch already exists
 48→	}
 49→
 50→	// Create orphan branch with empty tree
 51→	emptyTreeHash, err := checkpoint.BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
 52→	if err != nil {
 53→		return fmt.Errorf("failed to build empty tree: %w", err)
 54→	}
 55→
 56→	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
 57→	commitHash, err := checkpoint.CreateCommit(s.repo, emptyTreeHash, plumbing.ZeroHash, "Initialize trails branch", authorName, authorEmail)
 58→	if err != nil {
 59→		return fmt.Errorf("failed to create initial commit: %w", err)
 60→	}
 61→
 62→	newRef := plumbing.NewHashReference(refName, commitHash)
 63→	if err := s.repo.Storer.SetReference(newRef); err != nil {
 64→		return fmt.Errorf("failed to set branch reference: %w", err)
 65→	}
 66→	return nil
 67→}
 68→
 69→// Write writes trail metadata, discussion, checkpoints, and verification to the entire/trails/v1 branch.
 70→// Nil arguments are written as empty defaults.
 71→func (s *Store) Write(metadata *Metadata, discussion *Discussion, checkpoints *Checkpoints, verification *Verification) error {
 72→	if metadata.TrailID.IsEmpty() {
 73→		return errors.New("trail ID is required")
 74→	}
 75→
 76→	if err := s.EnsureBranch(); err != nil {
 77→		return fmt.Errorf("failed to ensure trails branch: %w", err)
 78→	}
 79→
 80→	commitHash, rootTreeHash, err := s.getBranchRef()
 81→	if err != nil {
 82→		return fmt.Errorf("failed to get branch ref: %w", err)
 83→	}
 84→
 85→	// Build blob entries for the trail's files
 86→	trailEntries, err := s.buildTrailEntries(metadata, discussion, checkpoints, verification)
 87→	if err != nil {
 88→		return err
 89→	}
 90→
 91→	// Splice into tree at [shard, suffix] — preserves sibling trails automatically
 92→	shard, suffix := metadata.TrailID.ShardParts()
 93→	newTreeHash, err := checkpoint.UpdateSubtree(
 94→		s.repo, rootTreeHash,
 95→		[]string{shard, suffix},
 96→		trailEntries,
 97→		checkpoint.UpdateSubtreeOptions{MergeMode: checkpoint.ReplaceAll},
 98→	)
 99→	if err != nil {
100→		return fmt.Errorf("failed to update subtree: %w", err)
101→	}
102→
103→	commitMsg := fmt.Sprintf("Trail: %s (%s)", metadata.Title, metadata.TrailID)
104→	return s.commitAndUpdateRef(newTreeHash, commitHash, commitMsg)
105→}
106→
107→// buildTrailEntries creates blob objects for a trail's files and returns them as tree entries.
108→func (s *Store) buildTrailEntries(metadata *Metadata, discussion *Discussion, checkpoints *Checkpoints, verification *Verification) ([]object.TreeEntry, error) {
109→	if discussion == nil {
110→		discussion = &Discussion{Comments: []Comment{}}
111→	}
112→	if checkpoints == nil {
113→		checkpoints = &Checkpoints{Checkpoints: []CheckpointRef{}}
114→	}
115→	if verification == nil {
116→		verification = &Verification{Events: []VerificationEvent{}}
117→	}
118→
119→	type fileSpec struct {
120→		name string
121→		data any
122→	}
123→	files := []fileSpec{
124→		{metadataFile, metadata},
125→		{discussionFile, discussion},
126→		{checkpointsFile, checkpoints},
127→		{verificationFile, verification},
128→	}
129→
130→	entries := make([]object.TreeEntry, 0, len(files))
131→	for _, f := range files {
132→		jsonBytes, err := json.MarshalIndent(f.data, "", "  ")
133→		if err != nil {
134→			return nil, fmt.Errorf("failed to marshal %s: %w", f.name, err)
135→		}
136→		blobHash, err := checkpoint.CreateBlobFromContent(s.repo, jsonBytes)
137→		if err != nil {
138→			return nil, fmt.Errorf("failed to create %s blob: %w", f.name, err)
139→		}
140→		entries = append(entries, object.TreeEntry{
141→			Name: f.name,
142→			Mode: filemode.Regular,
143→			Hash: blobHash,
144→		})
145→	}
146→
147→	return entries, nil
148→}
