393→// Delete removes a trail from the entire/trails/v1 branch.
394→func (s *Store) Delete(trailID ID) error {
395→	if err := ValidateID(string(trailID)); err != nil {
396→		return err
397→	}
398→
399→	if err := s.EnsureBranch(); err != nil {
400→		return fmt.Errorf("failed to ensure trails branch: %w", err)
401→	}
402→
403→	commitHash, rootTreeHash, err := s.getBranchRef()
404→	if err != nil {
405→		return fmt.Errorf("failed to get branch ref: %w", err)
406→	}
407→
408→	// Verify the trail exists by navigating the tree at O(depth)
409→	shard, suffix := trailID.ShardParts()
410→	if _, err := s.navigateToTrailTree(rootTreeHash, shard, suffix); err != nil {
411→		return err
412→	}
413→
414→	// Delete the trail's subtree by removing it from the shard directory
415→	newTreeHash, err := checkpoint.UpdateSubtree(
416→		s.repo, rootTreeHash,
417→		[]string{shard},
418→		nil,
419→		checkpoint.UpdateSubtreeOptions{
420→			MergeMode:   checkpoint.MergeKeepExisting,
421→			DeleteNames: []string{suffix},
422→		},
423→	)
424→	if err != nil {
425→		return fmt.Errorf("failed to update subtree: %w", err)
426→	}
427→
428→	commitMsg := fmt.Sprintf("Delete trail: %s", trailID)
429→	return s.commitAndUpdateRef(newTreeHash, commitHash, commitMsg)
430→}
431→
432→// navigateToTrailTree walks rootTree → shard → suffix and returns the trail's subtree.
433→func (s *Store) navigateToTrailTree(rootTreeHash plumbing.Hash, shard, suffix string) (*object.Tree, error) {
434→	rootTree, err := s.repo.TreeObject(rootTreeHash)
435→	if err != nil {
436→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
437→	}
438→
439→	shardEntry, err := rootTree.FindEntry(shard)
440→	if err != nil {
441→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
442→	}
443→
444→	shardTree, err := s.repo.TreeObject(shardEntry.Hash)
445→	if err != nil {
446→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
447→	}
448→
449→	trailEntry, err := shardTree.FindEntry(suffix)
450→	if err != nil {
451→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
452→	}
453→
454→	trailTree, err := s.repo.TreeObject(trailEntry.Hash)
455→	if err != nil {
456→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
457→	}
458→
459→	return trailTree, nil
460→}
461→
462→// readCheckpointsFromTrailTree reads checkpoints.json from a trail's subtree.
463→// Returns empty checkpoints if the file doesn't exist yet.
464→func (s *Store) readCheckpointsFromTrailTree(trailTree *object.Tree) (*Checkpoints, error) {
465→	cpEntry, err := trailTree.FindEntry(checkpointsFile)
466→	if err != nil {
467→		// No checkpoints file yet — return empty
468→		return &Checkpoints{Checkpoints: []CheckpointRef{}}, nil
469→	}
470→
471→	blob, err := s.repo.BlobObject(cpEntry.Hash)
472→	if err != nil {
473→		return nil, fmt.Errorf("failed to read checkpoints blob: %w", err)
474→	}
475→
476→	reader, err := blob.Reader()
477→	if err != nil {
478→		return nil, fmt.Errorf("failed to open checkpoints reader: %w", err)
479→	}
480→	defer reader.Close()
481→
482→	var checkpoints Checkpoints
483→	if err := json.NewDecoder(reader).Decode(&checkpoints); err != nil {
484→		return nil, fmt.Errorf("failed to decode checkpoints: %w", err)
485→	}
486→
487→	return &checkpoints, nil
488→}
