224→	errW := cmd.ErrOrStderr()
225→
226→	repo, err := strategy.OpenRepository(context.Background())
227→	if err != nil {
228→		return fmt.Errorf("failed to open repository: %w", err)
229→	}
230→
231→	// Determine base branch
232→	if base == "" {
233→		base = strategy.GetDefaultBranchName(repo)
234→		if base == "" {
235→			base = defaultBaseBranch
236→		}
237→	}
238→
239→	_, currentBranch, _ := IsOnDefaultBranch(context.Background()) //nolint:errcheck // best-effort detection
240→	interactive := !cmd.Flags().Changed("title") && !cmd.Flags().Changed("branch")
241→
242→	if interactive {
243→		// Interactive flow: title → body → branch (derived) → status
244→		if err := runTrailCreateInteractive(&title, &body, &branch, &statusStr); err != nil {
245→			return err
246→		}
247→	} else {
248→		// Non-interactive: derive missing values from provided flags
249→		if branch == "" {
250→			if cmd.Flags().Changed("title") {
251→				branch = slugifyTitle(title)
252→			} else {
253→				branch = currentBranch
254→			}
255→		}
256→		if title == "" {
257→			title = trail.HumanizeBranchName(branch)
258→		}
259→	}
260→	if branch == "" {
261→		return errors.New("branch name is required")
262→	}
263→
264→	// Create the branch if it doesn't exist
265→	needsCreation := branchNeedsCreation(repo, branch)
266→	if needsCreation {
267→		if err := createBranch(repo, branch); err != nil {
268→			return fmt.Errorf("failed to create branch %q: %w", branch, err)
269→		}
270→		fmt.Fprintf(w, "Created branch %s\n", branch)
271→	} else if currentBranch != branch {
272→		fmt.Fprintf(errW, "Note: trail will be created for branch %q (not the current branch)\n", branch)
273→	}
274→
275→	// Check if trail already exists for this branch
276→	store := trail.NewStore(repo)
277→	existing, _, err := store.FindByBranch(branch)
278→	if err == nil && existing != nil {
279→		fmt.Fprintf(w, "Trail already exists for branch %q (ID: %s)\n", branch, existing.TrailID)
280→		return nil
281→	}
282→
283→	// Determine status
284→	var trailStatus trail.Status
285→	if statusStr != "" {
286→		trailStatus = trail.Status(statusStr)
287→		if !trailStatus.IsValid() {
288→			return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
289→		}
290→	} else {
291→		trailStatus = trail.StatusDraft
292→	}
293→
294→	// Generate trail ID
295→	trailID, err := trail.GenerateID()
296→	if err != nil {
297→		return fmt.Errorf("failed to generate trail ID: %w", err)
298→	}
299→
300→	// Get author (GitHub username, falls back to git user.name)
301→	authorName := getTrailAuthor(repo)
302→
303→	now := time.Now()
304→	metadata := &trail.Metadata{
305→		TrailID:   trailID,
306→		Branch:    branch,
307→		Base:      base,
308→		Title:     title,
309→		Body:      body,
310→		Status:    trailStatus,
311→		Author:    authorName,
312→		Assignees: []string{},
313→		Labels:    []string{},
314→		CreatedAt: now,
315→		UpdatedAt: now,
316→	}
317→
318→	if err := store.Write(metadata, nil, nil, nil); err != nil {
319→		return fmt.Errorf("failed to create trail: %w", err)
320→	}
321→
322→	fmt.Fprintf(w, "Created trail %q for branch %s (ID: %s)\n", title, branch, trailID)
323→
324→	// Push the branch and trail data to origin
325→	if needsCreation {
326→		if err := pushBranchToOrigin(branch); err != nil {
327→			fmt.Fprintf(errW, "Warning: failed to push branch: %v\n", err)
328→		} else {
329→			fmt.Fprintf(w, "Pushed branch %s to origin\n", branch)
330→		}
331→	}
332→	if err := strategy.PushTrailsBranch(context.Background(), "origin"); err != nil {
333→		fmt.Fprintf(errW, "Warning: failed to push trail data: %v\n", err)
334→	}
335→
336→	// Checkout the branch if requested or prompted
337→	if needsCreation && currentBranch != branch {
338→		shouldCheckout := checkout
339→		if !shouldCheckout && !cmd.Flags().Changed("checkout") {
340→			// Interactive: ask whether to checkout
341→			form := NewAccessibleForm(
342→				huh.NewGroup(
343→					huh.NewConfirm().
344→						Title(fmt.Sprintf("Check out branch %s?", branch)).
345→						Value(&shouldCheckout),
346→				),
347→			)
348→			if formErr := form.Run(); formErr == nil && shouldCheckout {
349→				checkout = true
350→			}
351→		}
352→		if checkout {
353→			if err := CheckoutBranch(context.Background(), branch); err != nil {
354→				return fmt.Errorf("failed to checkout branch %q: %w", branch, err)
355→			}
356→			fmt.Fprintf(w, "Switched to branch %s\n", branch)
357→		}
358→	}
359→
360→	return nil
361→}
