385→func runTrailUpdate(w io.Writer, statusStr, title, body, branch string, labelAdd, labelRemove []string) error {
386→	repo, err := strategy.OpenRepository(context.Background())
387→	if err != nil {
388→		return fmt.Errorf("failed to open repository: %w", err)
389→	}
390→
391→	// Determine branch
392→	if branch == "" {
393→		branch, err = GetCurrentBranch(context.Background())
394→		if err != nil {
395→			return fmt.Errorf("failed to determine current branch: %w", err)
396→		}
397→	}
398→
399→	store := trail.NewStore(repo)
400→	metadata, _, err := store.FindByBranch(branch)
401→	if err != nil {
402→		return fmt.Errorf("failed to find trail: %w", err)
403→	}
404→	if metadata == nil {
405→		return fmt.Errorf("no trail found for branch %q", branch)
406→	}
407→
408→	// Interactive mode when no flags are provided
409→	noFlags := statusStr == "" && title == "" && body == "" && labelAdd == nil && labelRemove == nil
410→	if noFlags {
411→		// Build status options with current value as default.
412→		// Exclude "done" and "abandoned" unless the trail is already in that status
413→		// (otherwise the select would silently reset to the first option).
414→		var statusOptions []huh.Option[string]
415→		for _, s := range trail.ValidStatuses() {
416→			if (s == trail.StatusDone || s == trail.StatusAbandoned) && s != metadata.Status {
417→				continue
418→			}
419→			label := string(s)
420→			if s == metadata.Status {
421→				label += " (current)"
422→			}
423→			statusOptions = append(statusOptions, huh.NewOption(label, string(s)))
424→		}
425→		statusStr = string(metadata.Status)
426→		title = metadata.Title
427→		body = metadata.Body
428→
429→		form := NewAccessibleForm(
430→			huh.NewGroup(
431→				huh.NewSelect[string]().
432→					Title("Status").
433→					Options(statusOptions...).
434→					Value(&statusStr),
435→				huh.NewInput().
436→					Title("Title").
437→					Value(&title),
438→				huh.NewText().
439→					Title("Body").
440→					Value(&body),
441→			),
442→		)
443→		if formErr := form.Run(); formErr != nil {
444→			return fmt.Errorf("form cancelled: %w", formErr)
445→		}
446→	}
447→
448→	// Validate status if provided
449→	if statusStr != "" {
450→		status := trail.Status(statusStr)
451→		if !status.IsValid() {
452→			return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
453→		}
454→	}
455→
456→	err = store.Update(metadata.TrailID, func(m *trail.Metadata) {
457→		if statusStr != "" {
458→			m.Status = trail.Status(statusStr)
459→		}
460→		if title != "" {
461→			m.Title = title
462→		}
463→		if body != "" {
464→			m.Body = body
465→		}
466→		for _, l := range labelAdd {
467→			if !slices.Contains(m.Labels, l) {
468→				m.Labels = append(m.Labels, l)
469→			}
470→		}
471→		for _, l := range labelRemove {
472→			m.Labels = slices.DeleteFunc(m.Labels, func(v string) bool { return v == l })
473→		}
474→	})
475→	if err != nil {
476→		return fmt.Errorf("failed to update trail: %w", err)
477→	}
478→
479→	fmt.Fprintf(w, "Updated trail for branch %s\n", branch)
480→	return nil
481→}
