486→func formatValidStatuses() string {
487→	statuses := trail.ValidStatuses()
488→	names := make([]string, len(statuses))
489→	for i, s := range statuses {
490→		names[i] = string(s)
491→	}
492→	return strings.Join(names, ", ")
493→}
