495→// runTrailCreateInteractive runs the interactive form for trail creation.
496→// Prompts for title, body, branch (derived from title), and status.
497→func runTrailCreateInteractive(title, body, branch, statusStr *string) error {
498→	// Step 1: Title and body
499→	form := NewAccessibleForm(
500→		huh.NewGroup(
501→			huh.NewInput().
502→				Title("Trail title").
503→				Placeholder("What are you working on?").
504→				Value(title),
505→			huh.NewText().
506→				Title("Body (optional)").
507→				Value(body),
508→		),
509→	)
510→	if err := form.Run(); err != nil {
511→		return fmt.Errorf("form cancelled: %w", err)
512→	}
513→	*title = strings.TrimSpace(*title)
514→	if *title == "" {
515→		return errors.New("trail title is required")
516→	}
517→
518→	// Step 2: Branch (derived from title) and status
519→	suggested := slugifyTitle(*title)
520→	*branch = suggested
521→
522→	// Build status options, excluding done/abandoned
523→	var statusOptions []huh.Option[string]
524→	for _, s := range trail.ValidStatuses() {
525→		if s == trail.StatusDone || s == trail.StatusAbandoned {
526→			continue
527→		}
528→		statusOptions = append(statusOptions, huh.NewOption(string(s), string(s)))
529→	}
530→	if *statusStr == "" {
531→		*statusStr = string(trail.StatusDraft)
532→	}
533→
534→	form = NewAccessibleForm(
535→		huh.NewGroup(
536→			huh.NewInput().
537→				Title("Branch name").
538→				Placeholder(suggested).
539→				Value(branch),
540→			huh.NewSelect[string]().
541→				Title("Status").
542→				Options(statusOptions...).
543→				Value(statusStr),
544→		),
545→	)
546→	if err := form.Run(); err != nil {
547→		return fmt.Errorf("form cancelled: %w", err)
548→	}
549→	*branch = strings.TrimSpace(*branch)
550→	if *branch == "" {
551→		*branch = suggested
552→	}
553→	return nil
554→}
