556→// fetchTrailsBranch fetches the remote trails branch so we see trails from collaborators.
557→// Best-effort: silently ignores errors (e.g., no remote, no network).
558→func fetchTrailsBranch() {
559→	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
560→	defer cancel()
561→	branchName := paths.TrailsBranchName
562→	refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/origin/%s", branchName, branchName)
563→
564→	cmd := exec.CommandContext(ctx, "git", "fetch", "origin", refSpec)
565→	// Ensure non-interactive fetch in hook/agent contexts
566→	cmd.Stdin = nil
567→	cmd.Env = append(os.Environ(), "GIT_TERMINAL_PROMPT=0")
568→	_ = cmd.Run() //nolint:errcheck // best-effort fetch
569→}
