586→// slugifyTitle converts a title string into a branch-friendly slug.
587→// Example: "Add user authentication" -> "add-user-authentication"
588→func slugifyTitle(title string) string {
589→	s := strings.ToLower(strings.TrimSpace(title))
590→	// Replace spaces and underscores with hyphens
591→	s = strings.NewReplacer(" ", "-", "_", "-").Replace(s)
592→	// Remove anything that's not alphanumeric, hyphen, or slash
593→	var b strings.Builder
594→	prevHyphen := false
595→	for _, r := range s {
596→		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '/' {
597→			b.WriteRune(r)
598→			prevHyphen = false
599→		} else if r == '-' && !prevHyphen {
600→			b.WriteRune('-')
601→			prevHyphen = true
602→		}
603→	}
604→	return strings.Trim(b.String(), "-")
605→}
