613→// createBranch creates a new local branch pointing at HEAD without checking it out.
614→func createBranch(repo *git.Repository, branchName string) error {
615→	head, err := repo.Head()
616→	if err != nil {
617→		return fmt.Errorf("failed to get HEAD: %w", err)
618→	}
619→	ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), head.Hash())
620→	if err := repo.Storer.SetReference(ref); err != nil {
621→		return fmt.Errorf("failed to create branch ref: %w", err)
622→	}
623→	return nil
624→}
