638→//nolint:cyclop // sequential steps for adding a branch — splitting would obscure the flow
639→func newTrailBranchAddCmd() *cobra.Command {
640→	var baseBranch string
641→	var trailFlag string
642→
643→	cmd := &cobra.Command{
644→		Use:   "add [branch-name]",
645→		Short: "Add a branch to a trail",
646→		Long:  "Adds the current branch (or a named branch) to a trail. Uses stateless lookup to find the trail from the current branch.",
647→		Args:  cobra.MaximumNArgs(1),
648→		RunE: func(cmd *cobra.Command, args []string) error {
649→			repo, err := strategy.OpenRepository(context.Background())
650→			if err != nil {
651→				return fmt.Errorf("failed to open repository: %w", err)
652→			}
653→
654→			store := trail.NewStore(repo)
655→
656→			// Determine branch name to add
657→			var branchName string
658→			if len(args) > 0 {
659→				branchName = args[0]
660→			} else {
661→				branchName, err = GetCurrentBranch(context.Background())
662→				if err != nil {
663→					return fmt.Errorf("could not determine current branch: %w", err)
664→				}
665→			}
666→
667→			// Check if branch is already in a trail
668→			existing, existingEntry, findErr := store.FindByBranch(branchName)
669→			if findErr != nil {
670→				return fmt.Errorf("failed to look up branch: %w", findErr)
671→			}
672→			if existing != nil && existingEntry != nil {
673→				fmt.Fprintf(cmd.ErrOrStderr(), "Branch %q is already in trail %q\n", branchName, existing.Title)
674→				return nil
675→			}
676→
677→			// Resolve which trail to add to
678→			var targetTrail *trail.Metadata
679→			if trailFlag != "" {
680→				if err := trail.ValidateID(trailFlag); err != nil {
681→					return fmt.Errorf("invalid trail ID: %w", err)
682→				}
683→				targetTrail, _, _, _, err = store.Read(trail.ID(trailFlag))
684→				if err != nil {
685→					return fmt.Errorf("trail %s not found: %w", trailFlag, err)
686→				}
687→			} else {
688→				// Try to find trail from current branch (if adding a different branch)
689→				currentBranch, branchErr := GetCurrentBranch(context.Background())
690→				if branchErr == nil && currentBranch != branchName {
691→					targetTrail, _, _ = store.FindByBranch(currentBranch) //nolint:errcheck // best-effort lookup; nil targetTrail handled below
692→				}
693→				if targetTrail == nil {
694→					return errors.New("cannot determine trail; use --trail <id> to specify")
695→				}
696→			}
697→
698→			// Determine base branch
699→			if baseBranch == "" {
700→				baseBranch = getDefaultBranch(repo)
701→			}
702→
703→			// Generate branch entry ID
704→			entryID, err := trail.GenerateID()
705→			if err != nil {
706→				return fmt.Errorf("failed to generate branch ID: %w", err)
707→			}
708→
709→			entry := trail.BranchEntry{
710→				ID:         entryID.String(),
711→				Name:       branchName,
712→				BaseBranch: baseBranch,
713→				Status:     trail.BranchOpen,
714→				AddedAt:    time.Now().UTC(),
715→			}
716→
717→			if err := store.Update(targetTrail.TrailID, func(m *trail.Metadata) {
718→				m.Branches = append(m.Branches, entry)
719→			}); err != nil {
720→				return fmt.Errorf("failed to add branch: %w", err)
721→			}
722→
723→			fmt.Fprintf(cmd.OutOrStdout(), "Added branch %q to trail %q\n", branchName, targetTrail.Title)
724→			return nil
725→		},
726→	}
727→
728→	cmd.Flags().StringVar(&baseBranch, "base", "", "Base branch for stacking (default: repository default branch)")
729→	cmd.Flags().StringVar(&trailFlag, "trail", "", "Trail ID to add branch to")
730→
731→	return cmd
732→}
