624→// slugifyTitle converts a title string into a branch-friendly slug.
625→// Example: "Add user authentication" -> "add-user-authentication"
626→func slugifyTitle(title string) string {
627→	s := strings.ToLower(strings.TrimSpace(title))
628→	// Replace spaces and underscores with hyphens
629→	s = strings.NewReplacer(" ", "-", "_", "-").Replace(s)
630→	// Remove anything that's not alphanumeric, hyphen, or slash
631→	var b strings.Builder
632→	prevHyphen := false
633→	for _, r := range s {
634→		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '/' {
635→			b.WriteRune(r)
636→			prevHyphen = false
637→		} else if r == '-' && !prevHyphen {
638→			b.WriteRune('-')
639→			prevHyphen = true
640→		}
641→	}
642→	return strings.Trim(b.String(), "-")
643→}
