719→					return fmt.Errorf("invalid trail ID: %w", err)
720→				}
721→				targetTrail, _, _, _, err = store.Read(trail.ID(trailFlag))
722→				if err != nil {
723→					return fmt.Errorf("trail %s not found: %w", trailFlag, err)
724→				}
725→			} else {
