562→// runTrailCreateInteractive runs the interactive form for trail creation.
563→// Prompts for title, body, branch (derived from title), and status.
564→func runTrailCreateInteractive(title, body, branch, statusStr *string) error {
565→	// Step 1: Title and body
566→	form := NewAccessibleForm(
567→		huh.NewGroup(
568→			huh.NewInput().
569→				Title("Trail title").
570→				Placeholder("What are you working on?").
571→				Value(title),
572→			huh.NewText().
573→				Title("Body (optional)").
574→				Value(body),
575→		),
576→	)
577→	if err := form.Run(); err != nil {
578→		return fmt.Errorf("form cancelled: %w", err)
579→	}
580→	*title = strings.TrimSpace(*title)
581→	if *title == "" {
582→		return errors.New("trail title is required")
583→	}
584→
585→	// Step 2: Branch (derived from title) and status
586→	suggested := slugifyTitle(*title)
587→	*branch = suggested
588→
589→	// Build status options, excluding done/abandoned
590→	var statusOptions []huh.Option[string]
591→	for _, s := range trail.ValidStatuses() {
592→		if s == trail.StatusDone || s == trail.StatusAbandoned {
593→			continue
594→		}
595→		statusOptions = append(statusOptions, huh.NewOption(string(s), string(s)))
596→	}
597→	if *statusStr == "" {
598→		*statusStr = string(trail.StatusDraft)
599→	}
600→
601→	form = NewAccessibleForm(
602→		huh.NewGroup(
603→			huh.NewInput().
604→				Title("Branch name").
605→				Placeholder(suggested).
606→				Value(branch),
607→			huh.NewSelect[string]().
608→				Title("Status").
609→				Options(statusOptions...).
610→				Value(statusStr),
611→		),
612→	)
613→	if err := form.Run(); err != nil {
614→		return fmt.Errorf("form cancelled: %w", err)
615→	}
616→	*branch = strings.TrimSpace(*branch)
617→	if *branch == "" {
618→		*branch = suggested
619→	}
620→	return nil
621→}
