653→// slugifyTitle converts a title string into a branch-friendly slug.
654→// Example: "Add user authentication" -> "add-user-authentication"
655→func slugifyTitle(title string) string {
656→	s := strings.ToLower(strings.TrimSpace(title))
657→	// Replace spaces and underscores with hyphens
658→	s = strings.NewReplacer(" ", "-", "_", "-").Replace(s)
659→	// Remove anything that's not alphanumeric, hyphen, or slash
660→	var b strings.Builder
661→	prevHyphen := false
662→	for _, r := range s {
663→		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '/' {
664→			b.WriteRune(r)
665→			prevHyphen = false
666→		} else if r == '-' && !prevHyphen {
667→			b.WriteRune('-')
668→			prevHyphen = true
669→		}
670→	}
671→	return strings.Trim(b.String(), "-")
672→}
