705→//nolint:cyclop // sequential steps for adding a branch — splitting would obscure the flow
706→func newTrailBranchAddCmd() *cobra.Command {
707→	var baseBranch string
708→	var trailFlag string
709→
710→	cmd := &cobra.Command{
711→		Use:   "add [branch-name]",
712→		Short: "Add a branch to a trail",
713→		Long:  "Adds the current branch (or a named branch) to a trail. Uses stateless lookup to find the trail from the current branch.",
714→		Args:  cobra.MaximumNArgs(1),
715→		RunE: func(cmd *cobra.Command, args []string) error {
716→			repo, err := strategy.OpenRepository(context.Background())
717→			if err != nil {
718→				return fmt.Errorf("failed to open repository: %w", err)
719→			}
720→
721→			store := trail.NewStore(repo)
722→
723→			// Determine branch name to add
724→			var branchName string
725→			if len(args) > 0 {
726→				branchName = args[0]
727→			} else {
728→				branchName, err = GetCurrentBranch(context.Background())
729→				if err != nil {
730→					return fmt.Errorf("could not determine current branch: %w", err)
731→				}
732→			}
733→
734→			// Check if branch is already in a trail
735→			existing, existingEntry, findErr := store.FindByBranch(branchName)
736→			if findErr != nil {
737→				return fmt.Errorf("failed to look up branch: %w", findErr)
738→			}
739→			if existing != nil && existingEntry != nil {
740→				fmt.Fprintf(cmd.ErrOrStderr(), "Branch %q is already in trail %q\n", branchName, existing.Title)
741→				return nil
742→			}
743→
744→			// Resolve which trail to add to
745→			var targetTrail *trail.Metadata
746→			if trailFlag != "" {
747→				if err := trail.ValidateID(trailFlag); err != nil {
748→					return fmt.Errorf("invalid trail ID: %w", err)
749→				}
750→				targetTrail, _, _, _, err = store.Read(trail.ID(trailFlag))
751→				if err != nil {
752→					return fmt.Errorf("trail %s not found: %w", trailFlag, err)
753→				}
754→			} else {
755→				// Try to find trail from current branch (if adding a different branch)
756→				currentBranch, branchErr := GetCurrentBranch(context.Background())
757→				if branchErr == nil && currentBranch != branchName {
758→					targetTrail, _, _ = store.FindByBranch(currentBranch) //nolint:errcheck // best-effort lookup; nil targetTrail handled below
759→				}
760→				if targetTrail == nil {
761→					return errors.New("cannot determine trail; use --trail <id> to specify")
762→				}
763→			}
764→
765→			// Determine base branch
766→			if baseBranch == "" {
767→				baseBranch = getDefaultBranch(repo)
768→			}
769→
770→			// Generate branch entry ID
771→			entryID, err := trail.GenerateID()
772→			if err != nil {
773→				return fmt.Errorf("failed to generate branch ID: %w", err)
774→			}
775→
776→			entry := trail.BranchEntry{
777→				ID:         entryID.String(),
778→				Name:       branchName,
779→				BaseBranch: baseBranch,
780→				Status:     trail.BranchOpen,
781→				AddedAt:    time.Now().UTC(),
782→			}
783→
784→			if err := store.Update(targetTrail.TrailID, func(m *trail.Metadata) {
785→				m.Branches = append(m.Branches, entry)
786→			}); err != nil {
787→				return fmt.Errorf("failed to add branch: %w", err)
788→			}
789→
790→			fmt.Fprintf(cmd.OutOrStdout(), "Added branch %q to trail %q\n", branchName, targetTrail.Title)
791→			return nil
792→		},
793→	}
794→
795→	cmd.Flags().StringVar(&baseBranch, "base", "", "Base branch for stacking (default: repository default branch)")
796→	cmd.Flags().StringVar(&trailFlag, "trail", "", "Trail ID to add branch to")
797→
798→	return cmd
799→}
