150→// Read reads a trail by its ID from the entire/trails/v1 branch.
151→func (s *Store) Read(trailID ID) (*Metadata, *Discussion, *Checkpoints, *Verification, error) {
152→	if err := ValidateID(string(trailID)); err != nil {
153→		return nil, nil, nil, nil, err
154→	}
155→
156→	tree, err := s.getBranchTree()
157→	if err != nil {
158→		return nil, nil, nil, nil, err
159→	}
160→
161→	basePath := trailID.Path() + "/"
162→
163→	// Read metadata
164→	metadataEntry, err := tree.FindEntry(basePath + metadataFile)
165→	if err != nil {
166→		return nil, nil, nil, nil, fmt.Errorf("trail %s not found: %w", trailID, err)
167→	}
168→	metadataBlob, err := s.repo.BlobObject(metadataEntry.Hash)
169→	if err != nil {
170→		return nil, nil, nil, nil, fmt.Errorf("failed to read metadata blob: %w", err)
171→	}
172→	metadataReader, err := metadataBlob.Reader()
173→	if err != nil {
174→		return nil, nil, nil, nil, fmt.Errorf("failed to open metadata reader: %w", err)
175→	}
176→	defer metadataReader.Close()
177→
178→	var metadata Metadata
179→	if err := json.NewDecoder(metadataReader).Decode(&metadata); err != nil {
180→		return nil, nil, nil, nil, fmt.Errorf("failed to decode metadata: %w", err)
181→	}
182→
183→	// Read discussion (optional, may not exist yet)
184→	var discussion Discussion
185→	discussionEntry, err := tree.FindEntry(basePath + discussionFile)
186→	if err == nil {
187→		discussionBlob, blobErr := s.repo.BlobObject(discussionEntry.Hash)
188→		if blobErr == nil {
189→			discussionReader, readerErr := discussionBlob.Reader()
190→			if readerErr == nil {
191→				//nolint:errcheck,gosec // best-effort decode of optional discussion
192→				json.NewDecoder(discussionReader).Decode(&discussion)
193→				_ = discussionReader.Close()
194→			}
195→		}
196→	}
197→
198→	// Read checkpoints (optional, may not exist yet)
199→	var checkpoints Checkpoints
200→	checkpointsEntry, err := tree.FindEntry(basePath + checkpointsFile)

200→	checkpointsEntry, err := tree.FindEntry(basePath + checkpointsFile)
201→	if err == nil {
202→		checkpointsBlob, blobErr := s.repo.BlobObject(checkpointsEntry.Hash)
203→		if blobErr == nil {
204→			checkpointsReader, readerErr := checkpointsBlob.Reader()
205→			if readerErr == nil {
206→				//nolint:errcheck,gosec // best-effort decode of optional checkpoints
207→				json.NewDecoder(checkpointsReader).Decode(&checkpoints)
208→				_ = checkpointsReader.Close()
209→			}
210→		}
211→	}
212→
213→	// Read verification (optional, may not exist for older trails)
214→	var verification Verification
215→	verificationEntry, err := tree.FindEntry(basePath + verificationFile)
216→	if err == nil {
217→		verificationBlob, blobErr := s.repo.BlobObject(verificationEntry.Hash)
218→		if blobErr == nil {
219→			verificationReader, readerErr := verificationBlob.Reader()
220→			if readerErr == nil {
221→				//nolint:errcheck,gosec // best-effort decode of optional verification
222→				json.NewDecoder(verificationReader).Decode(&verification)
223→				_ = verificationReader.Close()
224→			}
225→		}
226→	}
227→
228→	return &metadata, &discussion, &checkpoints, &verification, nil
229→}
