317→// AddCheckpoint prepends a checkpoint reference to a trail's checkpoints list (newest first).
318→// Only reads and writes the checkpoints.json file — metadata and discussion are untouched.
319→// Uses CAS retry to handle concurrent writes to the trails branch.
320→func (s *Store) AddCheckpoint(trailID ID, ref CheckpointRef) error {
321→	if err := ValidateID(string(trailID)); err != nil {
322→		return err
323→	}
324→
325→	if err := s.EnsureBranch(); err != nil {
326→		return fmt.Errorf("failed to ensure trails branch: %w", err)
327→	}
328→
329→	for attempt := range maxCASRetries {
330→		err := s.addCheckpointOnce(trailID, ref)
331→		if err == nil {
332→			return nil
333→		}
334→		if !errors.Is(err, storage.ErrReferenceHasChanged) {
335→			return err
336→		}
337→		if attempt == maxCASRetries-1 {
338→			return fmt.Errorf("failed to add checkpoint after %d retries: %w", maxCASRetries, err)
339→		}
340→	}
341→	return nil
342→}
343→
344→// addCheckpointOnce performs a single attempt to prepend a checkpoint reference.
345→// Returns storage.ErrReferenceHasChanged (wrapped) if the branch moved concurrently.
346→func (s *Store) addCheckpointOnce(trailID ID, ref CheckpointRef) error {
347→	commitHash, rootTreeHash, err := s.getBranchRef()
348→	if err != nil {
349→		return fmt.Errorf("failed to get branch ref: %w", err)
350→	}
351→
352→	// Navigate to the trail's subtree and read only checkpoints.json
353→	shard, suffix := trailID.ShardParts()
354→	trailTree, err := s.navigateToTrailTree(rootTreeHash, shard, suffix)
355→	if err != nil {
356→		return fmt.Errorf("failed to read checkpoints for trail %s: %w", trailID, err)
357→	}
358→
359→	checkpoints, err := s.readCheckpointsFromTrailTree(trailTree)
360→	if err != nil {
361→		return fmt.Errorf("failed to read checkpoints for trail %s: %w", trailID, err)
362→	}
363→
364→	// Prepend new ref (newest first)
365→	checkpoints.Checkpoints = append(checkpoints.Checkpoints, CheckpointRef{})
366→	copy(checkpoints.Checkpoints[1:], checkpoints.Checkpoints[:len(checkpoints.Checkpoints)-1])
367→	checkpoints.Checkpoints[0] = ref
368→
369→	// Create new blob and splice back — MergeKeepExisting preserves metadata.json and discussion.json
370→	checkpointsJSON, err := json.MarshalIndent(checkpoints, "", "  ")
371→	if err != nil {
372→		return fmt.Errorf("failed to marshal checkpoints: %w", err)
373→	}
374→	blobHash, err := checkpoint.CreateBlobFromContent(s.repo, checkpointsJSON)
375→	if err != nil {
376→		return fmt.Errorf("failed to create checkpoints blob: %w", err)
377→	}
378→
379→	newTreeHash, err := checkpoint.UpdateSubtree(
380→		s.repo, rootTreeHash,
381→		[]string{shard, suffix},
382→		[]object.TreeEntry{{Name: checkpointsFile, Mode: filemode.Regular, Hash: blobHash}},
383→		checkpoint.UpdateSubtreeOptions{MergeMode: checkpoint.MergeKeepExisting},
384→	)
385→	if err != nil {
386→		return fmt.Errorf("failed to update subtree: %w", err)
387→	}
388→
389→	commitMsg := fmt.Sprintf("Add checkpoint to trail: %s", trailID)
390→	return s.commitAndUpdateRef(newTreeHash, commitHash, commitMsg)
391→}
392→
393→// Delete removes a trail from the entire/trails/v1 branch.
394→func (s *Store) Delete(trailID ID) error {
395→	if err := ValidateID(string(trailID)); err != nil {
396→		return err
397→	}
398→
399→	if err := s.EnsureBranch(); err != nil {
400→		return fmt.Errorf("failed to ensure trails branch: %w", err)
401→	}
402→
403→	commitHash, rootTreeHash, err := s.getBranchRef()
404→	if err != nil {
405→		return fmt.Errorf("failed to get branch ref: %w", err)
406→	}
407→
408→	// Verify the trail exists by navigating the tree at O(depth)
409→	shard, suffix := trailID.ShardParts()
410→	if _, err := s.navigateToTrailTree(rootTreeHash, shard, suffix); err != nil {
411→		return err
412→	}
413→
414→	// Delete the trail's subtree by removing it from the shard directory
415→	newTreeHash, err := checkpoint.UpdateSubtree(
416→		s.repo, rootTreeHash,
417→		[]string{shard},
418→		nil,
419→		checkpoint.UpdateSubtreeOptions{
420→			MergeMode:   checkpoint.MergeKeepExisting,
421→			DeleteNames: []string{suffix},
422→		},
423→	)
424→	if err != nil {
425→		return fmt.Errorf("failed to update subtree: %w", err)
426→	}
427→
428→	commitMsg := fmt.Sprintf("Delete trail: %s", trailID)
429→	return s.commitAndUpdateRef(newTreeHash, commitHash, commitMsg)
430→}
431→
432→// navigateToTrailTree walks rootTree → shard → suffix and returns the trail's subtree.
433→func (s *Store) navigateToTrailTree(rootTreeHash plumbing.Hash, shard, suffix string) (*object.Tree, error) {
434→	rootTree, err := s.repo.TreeObject(rootTreeHash)
435→	if err != nil {
436→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
437→	}
438→
439→	shardEntry, err := rootTree.FindEntry(shard)
440→	if err != nil {
441→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
442→	}
443→
444→	shardTree, err := s.repo.TreeObject(shardEntry.Hash)
445→	if err != nil {
446→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
447→	}
448→
449→	trailEntry, err := shardTree.FindEntry(suffix)
450→	if err != nil {
451→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
452→	}
453→
454→	trailTree, err := s.repo.TreeObject(trailEntry.Hash)
455→	if err != nil {
456→		return nil, fmt.Errorf("trail %s/%s not found: %w", shard, suffix, err)
457→	}
458→
459→	return trailTree, nil
460→}
461→
462→// readCheckpointsFromTrailTree reads checkpoints.json from a trail's subtree.
463→// Returns empty checkpoints if the file doesn't exist yet.
464→func (s *Store) readCheckpointsFromTrailTree(trailTree *object.Tree) (*Checkpoints, error) {
465→	cpEntry, err := trailTree.FindEntry(checkpointsFile)
466→	if err != nil {
467→		// No checkpoints file yet — return empty
468→		return &Checkpoints{Checkpoints: []CheckpointRef{}}, nil
469→	}
470→
471→	blob, err := s.repo.BlobObject(cpEntry.Hash)
472→	if err != nil {
473→		return nil, fmt.Errorf("failed to read checkpoints blob: %w", err)
474→	}
475→
476→	reader, err := blob.Reader()
477→	if err != nil {
478→		return nil, fmt.Errorf("failed to open checkpoints reader: %w", err)
479→	}
480→	defer reader.Close()
481→
482→	var checkpoints Checkpoints
483→	if err := json.NewDecoder(reader).Decode(&checkpoints); err != nil {
484→		return nil, fmt.Errorf("failed to decode checkpoints: %w", err)
485→	}
486→
487→	return &checkpoints, nil
488→}
489→
490→// commitAndUpdateRef creates a commit and updates the trails branch reference using CAS.
491→func (s *Store) commitAndUpdateRef(treeHash, parentHash plumbing.Hash, message string) error {
492→	refName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
493→	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
494→
495→	commitHash, err := checkpoint.CreateCommit(s.repo, treeHash, parentHash, message, authorName, authorEmail)
496→	if err != nil {
497→		return fmt.Errorf("failed to create commit: %w", err)
498→	}
499→
500→	newRef := plumbing.NewHashReference(refName, commitHash)
501→	oldRef := plumbing.NewHashReference(refName, parentHash)
502→
503→	err = s.repo.Storer.CheckAndSetReference(newRef, oldRef)
504→	if err != nil {
505→		if errors.Is(err, storage.ErrReferenceHasChanged) {
506→			return fmt.Errorf("trail branch ref changed concurrently: %w", err)
507→		}
508→		return fmt.Errorf("failed to update branch reference: %w", err)
509→	}
510→	return nil
511→}
512→
513→// getBranchRef returns the commit hash and root tree hash for the entire/trails/v1 branch HEAD
514→// without flattening the tree. Falls back to remote tracking branch if local is missing.
515→func (s *Store) getBranchRef() (commitHash, rootTreeHash plumbing.Hash, err error) {
516→	refName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
517→	ref, refErr := s.repo.Reference(refName, true)
518→	if refErr != nil {
519→		// Try remote tracking branch
520→		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.TrailsBranchName)
521→		ref, refErr = s.repo.Reference(remoteRefName, true)
522→		if refErr != nil {
523→			return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("trails branch not found: %w", refErr)
524→		}
525→	}
526→
527→	commit, err := s.repo.CommitObject(ref.Hash())
528→	if err != nil {
529→		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit: %w", err)
530→	}
531→
532→	return ref.Hash(), commit.TreeHash, nil
533→}
534→
535→// getBranchTree returns the tree for the entire/trails/v1 branch HEAD.
536→func (s *Store) getBranchTree() (*object.Tree, error) {
537→	_, rootTreeHash, err := s.getBranchRef()
538→	if err != nil {
539→		return nil, err
540→	}
541→
542→	tree, err := s.repo.TreeObject(rootTreeHash)
543→	if err != nil {
544→		return nil, fmt.Errorf("failed to get tree: %w", err)
545→	}
546→
547→	return tree, nil
548→}
