	output := buf.String()

	if strings.Contains(output, "Intent:") {
		t.Errorf("should not show Intent: when nil, got:\n%s", output)
	}
}
```

## Category 2: Store-level tests for CLI command logic

Rather than full integration tests (which require compiling the binary), add targeted store-level tests that verify the exact operations the CLI commands perform. Add these to `/Users/alex/workspace/cli/.worktrees/1/cmd/entire/cli/trail/store_test.go`.

### Test: branch add logic (store.Update appending a BranchEntry)

```go
func TestStore_BranchAdd(t *testing.T) {
	t.Parallel()
	repo := initTestRepo(t)
	store := NewStore(repo)

	trailID, _ := GenerateID()
	now := time.Now().Truncate(time.Second)

	// Create trail with one branch
	metadata := &Metadata{
		TrailID:   trailID,
		Title:     "Multi-branch",
		Status:    StatusActive,
		CreatedAt: now,
		UpdatedAt: now,
		Branches: []BranchEntry{
			{ID: "uuid-1", Name: "feature/core", BaseBranch: "main", Status: BranchOpen, AddedAt: now},
		},
	}
	if err := store.Write(metadata, nil, nil, nil); err != nil {
		t.Fatal(err)
	}

	// Add a second branch (same operation as CLI trail branch add)
	newEntryID, _ := GenerateID()
	newEntry := BranchEntry{
		ID:         newEntryID.String(),
		Name:       "feature/api",
		BaseBranch: "feature/core",
		Status:     BranchOpen,
		AddedAt:    time.Now().UTC(),
	}
	if err := store.Update(trailID, func(m *Metadata) {
		m.Branches = append(m.Branches, newEntry)
	}); err != nil {
		t.Fatal(err)
	}

	// Verify
	got, _, _, _, err := store.Read(trailID)
	if err != nil {
		t.Fatal(err)
	}
	if len(got.Branches) != 2 {
		t.Fatalf("expected 2 branches, got %d", len(got.Branches))
	}
	if got.Branches[1].Name != "feature/api" {
		t.Errorf("expected feature/api, got %s", got.Branches[1].Name)
	}
	if got.Branches[1].BaseBranch != "feature/core" {
		t.Errorf("expected base feature/core, got %s", got.Branches[1].BaseBranch)
	}

	// FindByBranch should find both
	_, entry1, _ := store.FindByBranch("feature/core")
	if entry1 == nil || entry1.ID != "uuid-1" {
		t.Error("expected to find feature/core")
	}
	_, entry2, _ := store.FindByBranch("feature/api")
	if entry2 == nil || entry2.Name != "feature/api" {
		t.Error("expected to find feature/api")
	}
}
```

### Test: set-pr logic

```go
func TestStore_SetPR(t *testing.T) {
	t.Parallel()
	repo := initTestRepo(t)
	store := NewStore(repo)

	trailID, _ := GenerateID()
	now := time.Now().Truncate(time.Second)

	metadata := &Metadata{
		TrailID:   trailID,
		Title:     "PR test",
		Status:    StatusActive,
		CreatedAt: now,
		UpdatedAt: now,
		Branches: []BranchEntry{
			{ID: "uuid-1", Name: "feature/core", BaseBranch: "main", Status: BranchOpen, AddedAt: now},
		},
	}
	if err := store.Write(metadata, nil, nil, nil); err != nil {
		t.Fatal(err)
	}

	// Set PR (same as CLI trail branch set-pr)
	if err := store.Update(trailID, func(m *Metadata) {
		for i := range m.Branches {
			if m.Branches[i].ID == "uuid-1" {
				m.Branches[i].PR = &PRRef{Number: 42}
				break
			}
		}
	}); err != nil {
		t.Fatal(err)
	}

	// Verify
	got, _, _, _, err := store.Read(trailID)
	if err != nil {
		t.Fatal(err)
	}
	if got.Branches[0].PR == nil || got.Branches[0].PR.Number != 42 {
		t.Error("expected PR #42")
	}

	// Replace PR (set-pr again)
	if err := store.Update(trailID, func(m *Metadata) {
		for i := range m.Branches {
			if m.Branches[i].ID == "uuid-1" {
				m.Branches[i].PR = &PRRef{Number: 99}
				break
			}
		}
	}); err != nil {
		t.Fatal(err)
	}

	got, _, _, _, err = store.Read(trailID)
	if err != nil {
		t.Fatal(err)
	}
	if got.Branches[0].PR == nil || got.Branches[0].PR.Number != 99 {
		t.Error("expected PR #99 after replacement")
	}
}
```

### Test: discard logic

```go
func TestStore_DiscardBranch(t *testing.T) {
	t.Parallel()
	repo := initTestRepo(t)
	store := NewStore(repo)

	trailID, _ := GenerateID()
	now := time.Now().Truncate(time.Second)

	metadata := &Metadata{
		TrailID:   trailID,
		Title:     "Discard test",
		Status:    StatusActive,
		CreatedAt: now,
		UpdatedAt: now,
		Branches: []BranchEntry{
			{ID: "uuid-1", Name: "feature/core", BaseBranch: "main", Status: BranchOpen, AddedAt: now},
			{ID: "uuid-2", Name: "feature/cleanup", BaseBranch: "main", Status: BranchOpen, AddedAt: now},
		},
	}
	if err := store.Write(metadata, nil, nil, nil); err != nil {
		t.Fatal(err)
	}

	// Discard second branch (same as CLI trail branch discard)
	if err := store.Update(trailID, func(m *Metadata) {
		for i := range m.Branches {
			if m.Branches[i].ID == "uuid-2" {
				m.Branches[i].Status = BranchDiscarded
				break
			}
		}
	}); err != nil {
		t.Fatal(err)
	}

	got, _, _, _, err := store.Read(trailID)
	if err != nil {
		t.Fatal(err)
	}
	if got.Branches[0].Status != BranchOpen {
		t.Error("first branch should still be open")
	}
	if got.Branches[1].Status != BranchDiscarded {
		t.Error("second branch should be discarded")
	}
}
```

### Test: trail create with intent and branches

```go
func TestStore_CreateWithIntentAndBranches(t *testing.T) {
	t.Parallel()
	repo := initTestRepo(t)
	store := NewStore(repo)

	trailID, _ := GenerateID()
	entryID, _ := GenerateID()
	now := time.Now().Truncate(time.Second)

	// Simulate what trail create now does
	metadata := &Metadata{
		TrailID:   trailID,
		Title:     "Auth system",
		Status:    StatusDraft,
		Author:    "alice",
		Assignees: []string{},
		Labels:    []string{},
		CreatedAt: now,
		UpdatedAt: now,
		Intent: &Intent{
			Kind:    "inline",
			Value:   "Add OAuth2 authentication",
			Content: "Add OAuth2 authentication",
		},
		Branches: []BranchEntry{
			{
				ID:         entryID.String(),
				Name:       "feature/auth",
				BaseBranch: "main",
				Status:     BranchOpen,
				AddedAt:    now,
			},
		},
		Branch: "feature/auth",
		Base:   "main",
	}

	if err := store.Write(metadata, nil, nil, nil); err != nil {
		t.Fatal(err)
	}

	got, _, _, _, err := store.Read(trailID)
	if err != nil {
		t.Fatal(err)
	}

	// Verify intent
	if got.Intent == nil {
		t.Fatal("expected intent")
	}
	if got.Intent.Kind != "inline" {
		t.Errorf("expected inline intent, got %s", got.Intent.Kind)
	}
	if got.Intent.Content != "Add OAuth2 authentication" {
		t.Errorf("unexpected intent content: %s", got.Intent.Content)
	}

	// Verify branches
	if len(got.Branches) != 1 {
		t.Fatalf("expected 1 branch, got %d", len(got.Branches))
	}
	if got.Branches[0].Name != "feature/auth" {
		t.Errorf("expected feature/auth, got %s", got.Branches[0].Name)
	}

	// Verify legacy compat
	if got.Branch != "feature/auth" {
		t.Errorf("expected legacy branch field, got %s", got.Branch)
	}

	// FindByBranch should work via Branches[]
	found, entry, err := store.FindByBranch("feature/auth")
	if err != nil || found == nil {
		t.Fatal("expected to find trail by branch")
	}
	if entry == nil {
		t.Fatal("expected branch entry (not legacy)")
	}
	if entry.Name != "feature/auth" {
		t.Errorf("expected feature/auth entry, got %s", entry.Name)
	}
}
```

