func TestStore_IntentWithFileKind(t *testing.T) {
	t.Parallel()
	repo := initTestRepo(t)
	store := NewStore(repo)

	trailID, _ := GenerateID()
	now := time.Now().Truncate(time.Second)

	metadata := &Metadata{
