256→func runTrailCreate(cmd *cobra.Command, title, body, base, branch, statusStr, intentFile, intentIssue, intentInline string, checkout bool) error {
257→	w := cmd.OutOrStdout()
258→	errW := cmd.ErrOrStderr()
259→
260→	repo, err := strategy.OpenRepository(context.Background())
