314→		return nil
315→	}
316→
317→	// Determine status
318→	var trailStatus trail.Status
319→	if statusStr != "" {
320→		trailStatus = trail.Status(statusStr)
321→		if !trailStatus.IsValid() {
322→			return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
323→		}
324→	} else {
