452→func runTrailUpdate(w io.Writer, statusStr, title, body, branch string, labelAdd, labelRemove []string) error {
453→	repo, err := strategy.OpenRepository(context.Background())
454→	if err != nil {
455→		return fmt.Errorf("failed to open repository: %w", err)
456→	}
457→
458→	// Determine branch
459→	if branch == "" {
460→		branch, err = GetCurrentBranch(context.Background())
461→		if err != nil {
462→			return fmt.Errorf("failed to determine current branch: %w", err)
463→		}
464→	}
465→
466→	store := trail.NewStore(repo)
467→	metadata, _, err := store.FindByBranch(branch)
468→	if err != nil {
469→		return fmt.Errorf("failed to find trail: %w", err)
470→	}
471→	if metadata == nil {
472→		return fmt.Errorf("no trail found for branch %q", branch)
473→	}
474→
475→	// Interactive mode when no flags are provided
476→	noFlags := statusStr == "" && title == "" && body == "" && labelAdd == nil && labelRemove == nil
477→	if noFlags {
478→		// Build status options with current value as default.
479→		// Exclude "done" and "abandoned" unless the trail is already in that status
480→		// (otherwise the select would silently reset to the first option).
481→		var statusOptions []huh.Option[string]
482→		for _, s := range trail.ValidStatuses() {
483→			if (s == trail.StatusDone || s == trail.StatusAbandoned) && s != metadata.Status {
484→				continue
485→			}
486→			label := string(s)
487→			if s == metadata.Status {
488→				label += " (current)"
489→			}
490→			statusOptions = append(statusOptions, huh.NewOption(label, string(s)))
491→		}
492→		statusStr = string(metadata.Status)
493→		title = metadata.Title
494→		body = metadata.Body
495→
496→		form := NewAccessibleForm(
497→			huh.NewGroup(
498→				huh.NewSelect[string]().
499→					Title("Status").
500→					Options(statusOptions...).
501→					Value(&statusStr),
502→				huh.NewInput().
503→					Title("Title").
504→					Value(&title),
505→				huh.NewText().
506→					Title("Body").
507→					Value(&body),
508→			),
509→		)
510→		if formErr := form.Run(); formErr != nil {
511→			return fmt.Errorf("form cancelled: %w", formErr)
512→		}
513→	}
514→
515→	// Validate status if provided
516→	if statusStr != "" {
517→		status := trail.Status(statusStr)
518→		if !status.IsValid() {
519→			return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
520→		}
521→	}
522→
523→	err = store.Update(metadata.TrailID, func(m *trail.Metadata) {
524→		if statusStr != "" {
525→			m.Status = trail.Status(statusStr)
526→		}
527→		if title != "" {
528→			m.Title = title
529→		}
530→		if body != "" {
531→			m.Body = body
532→		}
533→		for _, l := range labelAdd {
534→			if !slices.Contains(m.Labels, l) {
535→				m.Labels = append(m.Labels, l)
536→			}
537→		}
538→		for _, l := range labelRemove {
539→			m.Labels = slices.DeleteFunc(m.Labels, func(v string) bool { return v == l })
540→		}
541→	})
542→	if err != nil {
543→		return fmt.Errorf("failed to update trail: %w", err)
544→	}
545→
546→	fmt.Fprintf(w, "Updated trail for branch %s\n", branch)
547→	return nil
548→}
