260→// List returns all trail metadata from the entire/trails/v1 branch.
261→func (s *Store) List() ([]*Metadata, error) {
262→	tree, err := s.getBranchTree()
263→	if err != nil {
264→		// Branch doesn't exist yet — no trails
265→		return nil, nil //nolint:nilerr // Expected when no trails exist yet
266→	}
267→
268→	var trails []*Metadata
269→	entries := make(map[string]object.TreeEntry)
270→	if err := checkpoint.FlattenTree(s.repo, tree, "", entries); err != nil {
271→		return nil, fmt.Errorf("failed to flatten tree: %w", err)
272→	}
273→
274→	// Find all metadata.json files
275→	for path, entry := range entries {
276→		if !strings.HasSuffix(path, "/"+metadataFile) {
277→			continue
278→		}
279→
280→		blob, err := s.repo.BlobObject(entry.Hash)
281→		if err != nil {
282→			continue
283→		}
284→		reader, err := blob.Reader()
285→		if err != nil {
286→			continue
287→		}
288→
289→		var metadata Metadata
290→		decodeErr := json.NewDecoder(reader).Decode(&metadata)
291→		_ = reader.Close()
292→		if decodeErr != nil {
293→			continue
294→		}
295→
296→		trails = append(trails, &metadata)
297→	}
298→
299→	return trails, nil
300→}
