302→// Update updates an existing trail's metadata. It reads the current metadata,
303→// applies the provided update function, and writes it back.
304→func (s *Store) Update(trailID ID, updateFn func(*Metadata)) error {
305→	// ValidateID is called by Read, no need to duplicate here
306→	metadata, discussion, checkpoints, verification, err := s.Read(trailID)
307→	if err != nil {
308→		return fmt.Errorf("failed to read trail for update: %w", err)
309→	}
310→
311→	updateFn(metadata)
312→	metadata.UpdatedAt = time.Now()
313→
314→	return s.Write(metadata, discussion, checkpoints, verification)
315→}
