490→// commitAndUpdateRef creates a commit and updates the trails branch reference using CAS.
491→func (s *Store) commitAndUpdateRef(treeHash, parentHash plumbing.Hash, message string) error {
492→	refName := plumbing.NewBranchReferenceName(paths.TrailsBranchName)
493→	authorName, authorEmail := checkpoint.GetGitAuthorFromRepo(s.repo)
494→
495→	commitHash, err := checkpoint.CreateCommit(s.repo, treeHash, parentHash, message, authorName, authorEmail)
496→	if err != nil {
497→		return fmt.Errorf("failed to create commit: %w", err)
498→	}
499→
500→	newRef := plumbing.NewHashReference(refName, commitHash)
501→	oldRef := plumbing.NewHashReference(refName, parentHash)
502→
503→	err = s.repo.Storer.CheckAndSetReference(newRef, oldRef)
504→	if err != nil {
505→		if errors.Is(err, storage.ErrReferenceHasChanged) {
506→			return fmt.Errorf("trail branch ref changed concurrently: %w", err)
507→		}
508→		return fmt.Errorf("failed to update branch reference: %w", err)
509→	}
510→	return nil
511→}
