 15→// initTestRepo creates a test git repository with an initial commit.
 16→func initTestRepo(t *testing.T) *git.Repository {
 17→	t.Helper()
 18→
 19→	dir := t.TempDir()
 20→
 21→	ctx := context.Background()
 22→	cmds := [][]string{
 23→		{"git", "init", dir},
 24→		{"git", "-C", dir, "config", "user.name", "Test"},
 25→		{"git", "-C", dir, "config", "user.email", "test@test.com"},
 26→	}
 27→	for _, args := range cmds {
 28→		cmd := exec.CommandContext(ctx, args[0], args[1:]...)
 29→		if out, err := cmd.CombinedOutput(); err != nil {
 30→			t.Fatalf("command %v failed: %v\n%s", args, err, out)
 31→		}
 32→	}
 33→
 34→	// Create a file and commit
 35→	if err := os.WriteFile(filepath.Join(dir, "README.md"), []byte("# Test"), 0o644); err != nil {
 36→		t.Fatalf("failed to write file: %v", err)
 37→	}
 38→	commitCmds := [][]string{
 39→		{"git", "-C", dir, "add", "."},
 40→		{"git", "-C", dir, "commit", "-m", "Initial commit"},
 41→	}
 42→	for _, args := range commitCmds {
 43→		cmd := exec.CommandContext(ctx, args[0], args[1:]...)
 44→		if out, err := cmd.CombinedOutput(); err != nil {
 45→			t.Fatalf("command %v failed: %v\n%s", args, err, out)
 46→		}
 47→	}
 48→
 49→	repo, err := git.PlainOpen(dir)
 50→	if err != nil {
 51→		t.Fatalf("failed to open repo: %v", err)
 52→	}
 53→	return repo
 54→}
