		Status:    StatusDraft,
		Author:    "alice",
		Assignees: []string{},
		Labels:    []string{},
		CreatedAt: now,
		UpdatedAt: now,
		Intent: &Intent{
			Kind:    "inline",
			Value:   "Add OAuth2 authentication",
			Content: "Add OAuth2 authentication",
		},
		Branches: []BranchEntry{
			{
				ID:         entryID.String(),
				Name:       "feature/auth",
				BaseBranch: "main",
				Status:     BranchOpen,
				AddedAt:    now,
			},
		},
		Branch: "feature/auth",
		Base:   "main",
	}

	if err := store.Write(metadata, nil, nil, nil); err != nil {
		t.Fatal(err)
	}

	got, _, _, _, err := store.Read(trailID)
	if err != nil {
		t.Fatal(err)
	}

	// Verify intent
	if got.Intent == nil {
		t.Fatal("expected intent")
	}
	if got.Intent.Kind != "inline" {
		t.Errorf("expected inline intent, got %s", got.Intent.Kind)
	}
	if got.Intent.Content != "Add OAuth2 authentication" {
		t.Errorf("unexpected intent content: %s", got.Intent.Content)
	}

	// Verify branches
	if len(got.Branches) != 1 {
		t.Fatalf("expected 1 branch, got %d", len(got.Branches))
	}
	if got.Branches[0].Name != "feature/auth" {
		t.Errorf("expected feature/auth, got %s", got.Branches[0].Name)
	}

	// Verify legacy compat
	if got.Branch != "feature/auth" {
		t.Errorf("expected legacy branch field, got %s", got.Branch)
	}

	// FindByBranch should work via Branches[]
	found, entry, err := store.FindByBranch("feature/auth")
	if err != nil || found == nil {
		t.Fatal("expected to find trail by branch")
	}
	if entry == nil {
		t.Fatal("expected branch entry (not legacy)")
	}
	if entry.Name != "feature/auth" {
		t.Errorf("expected feature/auth entry, got %s", entry.Name)
	}
}
